import React, { useState } from 'react';

// 개별 노드 컴포넌트
const TreeNode = ({ node, parentPath = '', onSelect }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const hasChildren = node.children && node.children.length > 0;

  // 현재 노드의 전체 경로 계산
  const currentFullPath = parentPath ? `${parentPath}/${node.name}` : node.name;

  const handleNodeClick = (e) => {
    e.stopPropagation();
    if (hasChildren) setIsExpanded(!isExpanded);

    // [수정] 폴더 클릭 시 폴더 경로 정보만 부모로 전달
    onSelect({
      name: node.name,
      fullPath: currentFullPath,
    });
  };

  const nodeStyle = {
    cursor: 'pointer',
    padding: '4px 8px',
    display: 'flex',
    alignItems: 'center',
    gap: '8px',
    borderRadius: '4px',
    fontSize: '13px',
    transition: 'background 0.2s',
    userSelect: 'none',
    color: '#334155',
  };

  return (
    <div style={{ paddingLeft: '12px', marginTop: '2px' }}>
      <div
        className="tree-node"
        onClick={handleNodeClick}
        style={nodeStyle}
        onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#f1f5f9')}
        onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'transparent')}
      >
        <span style={{ fontSize: '10px', width: '12px', color: '#94a3b8' }}>
          {hasChildren ? (isExpanded ? '▼' : '▶') : ''}
        </span>
        <span style={{ fontSize: '16px' }}>{isExpanded ? '📂' : '📁'}</span>
        <span style={{ fontWeight: isExpanded ? '600' : '400' }}>{node.name}</span>
      </div>

      {hasChildren && isExpanded && (
        <div style={{ borderLeft: '1px dashed #cbd5e1', marginLeft: '8px' }}>
          {node.children.map((child, index) => (
            <TreeNode
              key={`${currentFullPath}-${index}`}
              node={child}
              parentPath={currentFullPath}
              onSelect={onSelect}
            />
          ))}
        </div>
      )}
    </div>
  );
};

// [수정] 트리 변환 로직: folder 경로만 사용하여 트리 생성 (groupname 제외)
const transformToTree = (paths) => {
  if (!paths) return [];
  const root = [];

  paths.forEach((path) => {
    // folder 문자열(예: "root/test/sub")을 분리하여 계층 생성
    const parts = path.folder.split('/');
    let currentLevel = root;

    parts.forEach((part) => {
      let existingNode = currentLevel.find((node) => node.name === part);
      if (!existingNode) {
        existingNode = { name: part, children: [] };
        currentLevel.push(existingNode);
      }
      currentLevel = existingNode.children;
    });
    // 기존에 있던 groupname 추가 로직 삭제됨
  });
  return root;
};

const TreeList = ({
  indata,
  title = 'Folder Structure',
  selectedData,
  onReload,
  showReload = false,
}) => {
  // 중복된 folder 경로가 있어도 transformToTree에서 자동으로 병합됨
  const categoryData = transformToTree(indata || []);

  const handleSelectNode = (data) => {
    if (selectedData) {
      selectedData(data);
    }
  };

  return (
    <div style={{ paddingRight: '5px' }}>
      <div style={headerStyle}>
        <h4 style={titleStyle}>{title}</h4>
        {showReload && (
          <button
            onClick={onReload}
            style={reloadBtnStyle}
            title="Reload Data"
            onMouseEnter={(e) => (e.currentTarget.style.backgroundColor = '#e2e8f0')}
            onMouseLeave={(e) => (e.currentTarget.style.backgroundColor = 'transparent')}
          >
            🔄
          </button>
        )}
      </div>

      <div style={containerStyle}>
        {categoryData.length > 0 ? (
          categoryData.map((item, index) => (
            <TreeNode key={index} node={item} onSelect={handleSelectNode} />
          ))
        ) : (
          <div style={emptyStyle}>No Folders</div>
        )}
      </div>
    </div>
  );
};

// --- 스타일 정의 ---
const headerStyle = {
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  marginBottom: '8px',
};

const titleStyle = {
  margin: 0, // margin-bottom 제거 (headerStyle에서 관리)
  fontSize: '12px',
  color: '#64748b',
  textTransform: 'uppercase',
  letterSpacing: '0.5px',
  fontWeight: '700',
};

const reloadBtnStyle = {
  background: 'none',
  border: 'none',
  cursor: 'pointer',
  fontSize: '14px',
  padding: '4px',
  borderRadius: '4px',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  transition: 'background 0.2s',
  color: '#64748b',
};

const containerStyle = {
  border: '1px solid #e2e8f0',
  padding: '8px 4px',
  borderRadius: '8px',
  backgroundColor: '#f8fafc',
  minHeight: '100%',
};

const emptyStyle = {
  padding: '20px',
  textAlign: 'center',
  color: '#94a3b8',
  fontSize: '12px',
};

export default TreeList;
