import React, { useEffect, useRef, useState, useCallback, useMemo } from 'react';
import ecStat from 'echarts-stat';

// 1. 컴포넌트 외부로 패딩 상수를 이동하여 참조값 고정 (무한 루프 방지 핵심)
const CHART_PAD = { top: 30, right: 30, bottom: 50, left: 60 };

const GradientChart = ({
  dataList = [],
  title = 'wafer',
  legend = 'seriesname',
  xKey = 'x',
  yKey = 'cdvalue',
  polyOrder = 5,
  pointStyle = 'circle',
  pointSize = 5,
  colors = [],
}) => {
  const containerRef = useRef(null);
  const canvasRef = useRef(null);
  const [visibleSeries, setVisibleSeries] = useState({});
  const [tooltip, setTooltip] = useState({ show: false, x: 0, y: 0, data: null, sInfo: null });

  // 데이터 그룹화 및 파싱
  const formattedData = useMemo(() => {
    // 방어 코드: dataList가 배열이 아니거나 비어있으면 빈 배열 반환
    if (!Array.isArray(dataList) || dataList.length === 0) return [];

    const groups = dataList.reduce((acc, item) => {
      const name = item[legend] || 'Default';
      if (!acc[name]) acc[name] = [];

      // xKey, yKey가 데이터에 존재하는지 확인 후 삽입
      const valX = Number(item[xKey]);
      const valY = Number(item[yKey]);

      if (!isNaN(valX) && !isNaN(valY)) {
        acc[name].push([valX, valY]);
      }
      return acc;
    }, {});

    const PARULA_COLORS = [
      '#352a87',
      '#0f5cdd',
      '#1481d6',
      '#06a4ca',
      '#2eb7a4',
      '#87bf77',
      '#d1bb59',
      '#fec832',
      '#f9fb0e',
    ];
    const SERIES_BASE_COLORS = ['#3b82f6', '#ef4444', '#10b981', '#f59e0b', '#8b5cf6', '#06b6d4'];

    const seriesNames = Object.keys(groups);

    return seriesNames.map((name, idx) => {
      const raw = groups[name];
      const sorted = [...raw].sort((a, b) => a[0] - b[0]);
      const reg = ecStat.regression('polynomial', sorted, polyOrder);
      const yValues = raw.map((p) => p[1]);

      return {
        name,
        raw,
        trend: reg.points,
        yRange: [Math.min(...yValues), Math.max(...yValues)],
        seriesIndex: idx,
        colorPalette:
          seriesNames.length === 1
            ? colors.length > 0
              ? colors
              : PARULA_COLORS
            : SERIES_BASE_COLORS,
        // sInfo에서 사용할 대표 색상을 trendColor로 통일
        trendColor:
          seriesNames.length === 1 ? '#333' : SERIES_BASE_COLORS[idx % SERIES_BASE_COLORS.length],
      };
    });
  }, [dataList, xKey, yKey, legend, polyOrder]);

  useEffect(() => {
    if (formattedData.length > 0) {
      const initialVisible = {};
      formattedData.forEach((s) => (initialVisible[s.name] = true));
      setVisibleSeries(initialVisible);
    }
  }, [formattedData]);

  const minMax = useMemo(() => {
    // 데이터가 없으면 계산 자체를 하지 않음
    if (!formattedData || formattedData.length === 0) {
      return { xMin: 0, xMax: 1, yMin: 0, yMax: 1 };
    }

    const allPoints = formattedData.flatMap((s) => s.raw);
    const xVals = allPoints.map((p) => p[0]);
    const yVals = allPoints.map((p) => p[1]);

    const xMin = Math.min(...xVals);
    const xMax = Math.max(...xVals);
    const yMin = Math.min(...yVals);
    const yMax = Math.max(...yVals);

    const xR = xMax - xMin;
    const yR = yMax - yMin;

    // 범위가 0인 경우(점 하나)를 대비한 마진 설정
    const xM = xR === 0 ? 10 : xR * 0.05;
    const yM = yR === 0 ? 10 : yR * 0.05;

    return {
      xMin: xMin - xM,
      xMax: xMax + xM,
      yMin: yMin - yM,
      yMax: yMax + yM,
    };
  }, [formattedData]);

  // 색상을 받아서 30% 정도 어둡게 만들어 테두리 색상으로 반환하는 함수
  const getStrokeColor = (hex) => {
    const darken = 0.1; // 밝기 비율
    let r = parseInt(hex.slice(1, 3), 16);
    let g = parseInt(hex.slice(3, 5), 16);
    let b = parseInt(hex.slice(5, 7), 16);

    r = Math.floor(r * darken);
    g = Math.floor(g * darken);
    b = Math.floor(b * darken);

    return `rgb(${r}, ${g}, ${b})`;
  };

  // 도형 그리기 함수
  const drawShape = (ctx, x, y, size, fillColor, type, drawToolTip = false) => {
    const strokeColor = getStrokeColor(fillColor);

    ctx.beginPath();
    ctx.fillStyle = fillColor;

    if (drawToolTip) {
      ctx.strokeStyle = '#312f2f';
      ctx.lineWidth = 2;
    } else {
      ctx.strokeStyle = strokeColor;
      ctx.lineWidth = 0.5;
    }
    switch (type) {
      case 'rect': // 사각형
        ctx.rect(x - size / 2, y - size / 2, size, size);
        break;
      case 'circle': // 원
        ctx.arc(x, y, size / 2, 0, Math.PI * 2);
        break;
      case 'diamond': // 마름모
        ctx.moveTo(x, y - size / 2);
        ctx.lineTo(x + size / 2, y);
        ctx.lineTo(x, y + size / 2);
        ctx.lineTo(x - size / 2, y);
        break;
      case 'tri-up': // 정삼각형
        ctx.moveTo(x, y - size / 2);
        ctx.lineTo(x + size / 2, y + size / 2);
        ctx.lineTo(x - size / 2, y + size / 2);
        break;
      case 'tri-down': // 역삼각형
        ctx.moveTo(x - size / 2, y - size / 2);
        ctx.lineTo(x + size / 2, y - size / 2);
        ctx.lineTo(x, y + size / 2);
        break;
      case 'tri-left': // 왼쪽 삼각형
        ctx.moveTo(x + size / 2, y - size / 2);
        ctx.lineTo(x + size / 2, y + size / 2);
        ctx.lineTo(x - size / 2, y);
        break;
      case 'tri-right': // 오른쪽 삼각형
        ctx.moveTo(x - size / 2, y - size / 2);
        ctx.lineTo(x + size / 2, y);
        ctx.lineTo(x - size / 2, y + size / 2);
        break;
      default:
        break;
    }

    ctx.closePath();
    ctx.fill();
    ctx.stroke();
  };

  const drawChart = useCallback(() => {
    const canvas = canvasRef.current;
    const container = containerRef.current;
    if (!canvas || !container) return;
    if (!canvas || !container || formattedData.length === 0) return;

    const ctx = canvas.getContext('2d');
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const dpr = window.devicePixelRatio || 1;
    const { width, height } = container.getBoundingClientRect();

    canvas.width = width * dpr;
    canvas.height = height * dpr;
    ctx.scale(dpr, dpr);

    // 좌표 변환 함수
    const toPxX = (v) =>
      CHART_PAD.left +
      ((v - minMax.xMin) / (minMax.xMax - minMax.xMin)) *
        (width - CHART_PAD.left - CHART_PAD.right);
    const toPxY = (v) =>
      height -
      CHART_PAD.bottom -
      ((v - minMax.yMin) / (minMax.yMax - minMax.yMin)) *
        (height - CHART_PAD.top - CHART_PAD.bottom);

    ctx.clearRect(0, 0, width, height);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, width, height);

    // --- 그리드 및 축 그리기 ---
    ctx.strokeStyle = '#d8d3d3';
    ctx.lineWidth = 1;
    ctx.fillStyle = '#888';
    ctx.font = '11px sans-serif';

    // Y축 그리드 및 라벨
    const yStep = (minMax.yMax - minMax.yMin) / 5;
    for (let i = 0; i <= 5; i++) {
      const val = minMax.yMin + yStep * i;
      const py = toPxY(val);
      ctx.beginPath();
      ctx.moveTo(CHART_PAD.left, py);
      ctx.lineTo(width - CHART_PAD.right, py);
      ctx.stroke();
      ctx.textAlign = 'right';
      ctx.fillText(val.toFixed(0), CHART_PAD.left - 10, py + 4);
    }
    // X축 그리드 및 라벨
    for (let i = 0; i <= 5; i++) {
      const val = minMax.xMin + ((minMax.xMax - minMax.xMin) / 5) * i;
      const px = toPxX(val);
      ctx.beginPath();
      ctx.moveTo(px, CHART_PAD.top);
      ctx.lineTo(px, height - CHART_PAD.bottom);
      ctx.stroke();
      ctx.textAlign = 'center';
      if (
        xKey === 'chipx' ||
        xKey === 'chipy' ||
        xKey === 'shotx' ||
        xKey === 'shoty' ||
        xKey === 'radius'
      ) {
        if (i === 0) ctx.fillText('0', px, height - CHART_PAD.bottom + 20);
        else if (i === 5) ctx.fillText(minMax.xMax.toFixed(0), px, height - CHART_PAD.bottom + 20);
        else ctx.fillText(val.toFixed(0), px, height - CHART_PAD.bottom + 20);
      } else {
        ctx.fillText(val.toFixed(0), px, height - CHART_PAD.bottom + 20);
      }
    }
    if (xKey === 'x' || xKey === 'y') {
      ctx.beginPath();
      ctx.moveTo(toPxX(0), CHART_PAD.top);
      ctx.lineTo(toPxX(0), height - CHART_PAD.bottom);
      ctx.stroke();
      ctx.fillText('0', toPxX(0), height - CHART_PAD.bottom + 20);
    }

    // --- 데이터 렌더링 ---
    const hexToRgb = (hex) => {
      const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
      return result
        ? [parseInt(result[1], 16), parseInt(result[2], 16), parseInt(result[3], 16)]
        : [0, 0, 0];
    };
    let tipcolor = '#FFF';
    formattedData.forEach((s) => {
      if (!visibleSeries[s.name]) return;
      const isSingle = formattedData.length === 1;

      s.raw.forEach(([x, y]) => {
        const ratio = Math.max(0, Math.min(1, (y - s.yRange[0]) / (s.yRange[1] - s.yRange[0])));
        let finalColor;
        if (isSingle) {
          const pos = ratio * (s.colorPalette.length - 1);
          const i = Math.floor(pos);
          const c1 = hexToRgb(s.colorPalette[i]);
          const c2 = hexToRgb(s.colorPalette[Math.min(i + 1, s.colorPalette.length - 1)]);
          const r = Math.round(c1[0] + (c2[0] - c1[0]) * (pos - i));
          const g = Math.round(c1[1] + (c2[1] - c1[1]) * (pos - i));
          const b = Math.round(c1[2] + (c2[2] - c1[2]) * (pos - i));
          finalColor = `rgb(${r},${g},${b})`;
        } else {
          const base = hexToRgb(s.colorPalette[s.seriesIndex % s.colorPalette.length]);
          const r = Math.round(base[0] + (255 - base[0]) * (1 - ratio));
          const g = Math.round(base[1] + (255 - base[1]) * (1 - ratio));
          const b = Math.round(base[2] + (255 - base[2]) * (1 - ratio));
          finalColor = `rgb(${r},${g},${b})`;
        }
        // 도형 그리기 호출부 수정 => type 추가 전달
        drawShape(ctx, toPxX(x), toPxY(y), pointSize, finalColor, pointStyle, false);
        if (tooltip.show && tooltip.data[0] === x && tooltip.data[1] === y) {
          tipcolor = finalColor;
        }
      });

      if (tooltip.show) {
        drawShape(
          ctx,
          toPxX(tooltip.data[0]),
          toPxY(tooltip.data[1]),
          pointSize + 4,
          tipcolor,
          pointStyle,
          true,
        );
      }

      // 추세선
      ctx.strokeStyle = s.trendColor;
      ctx.lineWidth = 2;
      ctx.beginPath();
      s.trend.forEach(([tx, ty], i) => {
        const px = toPxX(tx);
        const py = toPxY(ty);
        if (i === 0) ctx.moveTo(px, py);
        else ctx.lineTo(px, py);
      });
      ctx.stroke();
      ctx.setLineDash([]);
    });
  }, [formattedData, visibleSeries, minMax, tooltip]);

  useEffect(() => {
    const container = containerRef.current;
    if (!container || formattedData.length === 0) return;

    // 1. 초기 렌더링 및 데이터 변경 시 즉시 실행
    // requestAnimationFrame으로 감싸서 브라우저의 페인팅 주기와 맞춥니다.
    const rafId = window.requestAnimationFrame(() => {
      drawChart();
    });

    // 2. 리사이즈 감시
    const ro = new ResizeObserver((entries) => {
      for (let entry of entries) {
        // 크기가 0인 경우는 그리지 않음 (탭 전환이나 숨김 처리 대비)
        if (entry.contentRect.width > 0 && entry.contentRect.height > 0) {
          window.requestAnimationFrame(drawChart);
        }
      }
    });

    ro.observe(container);

    return () => {
      window.cancelAnimationFrame(rafId);
      ro.disconnect();
    };
  }, [drawChart]);

  const handleMouseMove = (e) => {
    if (!canvasRef.current) return;
    const rect = canvasRef.current.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    const dataX =
      minMax.xMin +
      ((mx - CHART_PAD.left) / (rect.width - CHART_PAD.left - CHART_PAD.right)) *
        (minMax.xMax - minMax.xMin);
    const dataY =
      minMax.yMin +
      ((rect.height - CHART_PAD.bottom - my) / (rect.height - CHART_PAD.top - CHART_PAD.bottom)) *
        (minMax.yMax - minMax.yMin);

    let closest = null;
    let minDistance = 20;

    formattedData.forEach((s) => {
      if (!visibleSeries[s.name]) return;
      s.raw.forEach((p) => {
        const dx = (p[0] - dataX) * (rect.width / (minMax.xMax - minMax.xMin));
        const dy = (p[1] - dataY) * (rect.height / (minMax.yMax - minMax.yMin));
        const dist = Math.sqrt(dx * dx + dy * dy);
        if (dist < minDistance) {
          minDistance = dist;
          closest = { data: p, sInfo: s };
        }
      });
    });

    if (closest)
      setTooltip({ show: true, x: mx + 15, y: my - 70, data: closest.data, sInfo: closest.sInfo });
    else setTooltip((prev) => ({ ...prev, show: false }));
  };

  if (!dataList || dataList.length === 0) {
    return <div style={{ padding: '20px', color: '#666' }}>No Data Available</div>;
  }

  return (
    <div style={mainContainerStyle}>
      <div style={contentWrapperStyle}>
        <div ref={containerRef} style={canvasWrapperStyle}>
          <canvas
            ref={canvasRef}
            className="gradient-canvas-chart"
            keyid={title}
            style={{ width: '100%', height: '100%', display: 'block' }}
            onMouseMove={handleMouseMove}
            onMouseLeave={() => setTooltip((p) => ({ ...p, show: false }))}
          />
          {tooltip.show && (
            <div
              style={{
                ...tooltipStyle,
                left: tooltip.x,
                top: tooltip.y,
                // baseColor 대신 trendColor 사용
                border: `1.5px solid ${tooltip.sInfo.trendColor}`,
              }}
            >
              <div style={{ fontSize: '10px', color: '#999' }}>{tooltip.sInfo.name}</div>
              <div style={{ fontSize: '14px', fontWeight: '900', color: tooltip.sInfo.trendColor }}>
                {yKey}: {tooltip.data[1].toFixed(2)}
              </div>
              <div style={{ fontSize: '11px', color: '#666' }}>
                {xKey}: {tooltip.data[0].toFixed(2)}
              </div>
            </div>
          )}
        </div>
        {formattedData.length >= 2 && (
          <div style={legendContainerStyle}>
            {formattedData.map((s) => (
              <div
                key={s.name}
                onClick={() => setVisibleSeries((p) => ({ ...p, [s.name]: !p[s.name] }))}
                style={{ ...legendItemStyle, opacity: visibleSeries[s.name] ? 1 : 0.3 }}
              >
                <div style={{ ...dotStyle, backgroundColor: s.trendColor }} />
                <span>{s.name}</span>
              </div>
            ))}
          </div>
        )}
      </div>
    </div>
  );
};

// --- 스타일 정의 ---
const mainContainerStyle = {
  width: '100%',
  height: '100%',
  display: 'flex',
  flexDirection: 'column',
  backgroundColor: '#fff',
  padding: '10px',
  boxSizing: 'border-box',

  // --- 테두리 및 디자인 추가 ---
  border: '1px solid #e2e8f0', // 연한 회색 테두리
  borderRadius: '12px', // 모서리 둥글게
  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1), 0 2px 4px -1px rgba(0, 0, 0, 0.06)', // 은은한 그림자
};

const titleStyle = {
  fontSize: '19px',
  fontWeight: '500',
  color: '#1e293b',
  marginBottom: '3px',
  textAlign: 'center', // Center 정렬
  width: '100%',
};

const contentWrapperStyle = {
  display: 'flex',
  flex: 1,
  gap: '15px',
  minHeight: 0,
};

const legendContainerStyle = {
  width: '110px',
  display: 'flex',
  flexDirection: 'column',
  gap: '15px',
  paddingTop: '35px',
  paddingLeft: '5px',
};

const legendItemStyle = {
  display: 'flex',
  alignItems: 'center',
  cursor: 'pointer',
  fontSize: '12px',
  fontWeight: '600',
  color: '#475569',
};

const dotStyle = { width: '8px', height: '8px', borderRadius: '50%', marginRight: '8px' };

const canvasWrapperStyle = { flex: 1, position: 'relative', minWidth: 0 };

const tooltipStyle = {
  position: 'absolute',
  width: '130px',
  pointerEvents: 'none',
  backgroundColor: 'rgba(255,255,255,0.95)',
  boxShadow: '0 4px 12px rgba(0,0,0,0.1)',
  borderRadius: '6px',
  padding: '8px',
  zIndex: 10,
};

export default GradientChart;
