import React, { useState, useMemo, useEffect } from 'react';
import axios from 'axios';
import CustomAlert from './CustomAlert';
import { captureLog } from './logService';

const AddEmployeeForm = ({ user, dataType = 'Gen' }) => {
  // 1. 상태 관리
  const [formData, setFormData] = useState({
    EMP_ID: '',
    LOGIN_ID: '',
    PASSWORD: '',
    EMP_NAME: '',
    DEPT_CD: '', // 부서 코드
    DEPT_NAME: '', // 부서명
    POSITION_CD: 'STF',
    JOB_TYPE: 'IT',
    EMAIL: '',
    PHONE_NO: '',
    AUTH_LEVEL: 1,
    SEC_LEVEL: 1,
  });

  const [employees, setEmployees] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');
  const [alertConfig, setAlertConfig] = useState({ isOpen: false, title: '', message: '' });
  const [departments, setDepartments] = useState([]); // 실시간 부서 목록

  const currentYear = new Date().getFullYear();

  // 부서 마스터 데이터 (자동 매핑용)
  const localDeptMaster = [
    { cd: 'D001', name: 'IT 개발팀' },
    { cd: 'D002', name: '인사팀' },
    { cd: 'D003', name: '품질관리팀' },
    { cd: 'D004', name: '생산관리팀' },
    { cd: 'D005', name: '영업팀' },
  ];

  const localInitialData = [
    {
      EMP_ID: 'E2024001',
      EMP_NAME: '김철수',
      DEPT_NAME: 'IT 개발팀',
      DEPT_CD: 'D001',
      AUTH_LEVEL: 1,
      SEC_LEVEL: 1,
      EMAIL: 'chulsoo@company.com',
      STATUS_CD: 'JOIN',
    },
    {
      EMP_ID: 'E2024002',
      EMP_NAME: '이영희',
      DEPT_NAME: '인사팀',
      DEPT_CD: 'D002',
      AUTH_LEVEL: 2,
      SEC_LEVEL: 2,
      EMAIL: 'younghee@company.com',
      STATUS_CD: 'JOIN',
    },
  ];

  // 2. 부서 데이터 로딩 로직 추가
  useEffect(() => {
    const fetchDepartments = async () => {
      if (dataType === 'Api') {
        try {
          const response = await axios.get(
            'http://localhost:8081/api/v1/departments/with-employees',
          );
          // DTO 구조(deptCd, deptName)에 맞춰 매핑
          const mappedDepts = response.data.map((d) => ({
            cd: d.deptCd,
            name: d.deptName,
          }));
          setDepartments(mappedDepts);
        } catch (error) {
          console.error('부서 로드 실패:', error);
          setDepartments(localDeptMaster); // 실패 시 로컬 데이터로 폴백
        }
      } else {
        setDepartments(localDeptMaster);
      }
    };
    fetchDepartments();
  }, [dataType]);

  useEffect(() => {
    const fetchEmployees = async () => {
      setIsLoading(true);
      if (dataType === 'Gen') {
        setEmployees(localInitialData);
        setIsLoading(false);
      } else {
        try {
          const response = await axios.get('http://localhost:8081/api/v1/employees');
          const mappedData = response.data.map((emp) => ({
            EMP_ID: emp.empId,
            EMP_NAME: emp.empName,
            DEPT_CD: emp.department ? emp.department.deptCd : '',
            DEPT_NAME: emp.department ? emp.department.deptName : '',
            AUTH_LEVEL: emp.authLevel,
            SEC_LEVEL: emp.secLevel,
            EMAIL: emp.email,
            PHONE_NO: emp.phoneNo,
            STATUS_CD: emp.statusCd,
          }));
          setEmployees(mappedData);
        } catch (error) {
          setAlertConfig({ isOpen: true, title: '오류', message: '사원정보 로드 실패' });
        } finally {
          setIsLoading(false);
        }
      }
    };
    fetchEmployees();
  }, [dataType]);

  const closeAlert = () => setAlertConfig({ ...alertConfig, isOpen: false });

  const handleChange = (e) => {
    const { name, value } = e.target;

    // 부서명 선택 시 코드 자동 매핑 로직
    if (name === 'DEPT_NAME') {
      const selectedDept = departments.find((d) => d.name === value);
      setFormData({
        ...formData,
        DEPT_NAME: value,
        DEPT_CD: selectedDept ? selectedDept.cd : '',
      });
    } else {
      setFormData({ ...formData, [name]: value });
    }
  };

  const handleKeyDown = (e) => {
    if (e.key === 'Enter') setSearchTerm(inputValue);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!formData.EMP_ID || !formData.LOGIN_ID || !formData.DEPT_NAME) {
      setAlertConfig({
        isOpen: true,
        title: '필수입력',
        message: '사번, ID, 성명, 부서는 필수입니다.',
      });
      return;
    }

    try {
      if (dataType === 'Api') {
        // 서버가 기대하는 필드명(camelCase)으로 변환하여 전송
        const requestData = {
          empId: formData.EMP_ID,
          loginId: formData.LOGIN_ID,
          password: formData.PASSWORD,
          empName: formData.EMP_NAME,
          department: {
            deptCd: formData.DEPT_CD,
            deptName: formData.DEPT_NAME,
          },
          email: formData.EMAIL,
          phoneNo: formData.PHONE_NO,
          authLevel: parseInt(formData.AUTH_LEVEL),
          secLevel: parseInt(formData.SEC_LEVEL),
          statusCd: 'JOIN',
        };

        await axios.post('http://localhost:8081/api/v1/employees/register', requestData);
        captureLog(user, 'ADD_EMPLOYEE', 'ADD');
      }
      setEmployees([{ ...formData, STATUS_CD: 'JOIN' }, ...employees]);
      setAlertConfig({ isOpen: true, title: '등록 성공', message: '직원 정보가 등록되었습니다.' });

      setFormData({
        EMP_ID: '',
        LOGIN_ID: '',
        PASSWORD: '',
        EMP_NAME: '',
        DEPT_CD: '',
        DEPT_NAME: '',
        EMAIL: '',
        PHONE_NO: '',
        AUTH_LEVEL: 1,
        SEC_LEVEL: 1,
        POSITION_CD: 'STF',
        JOB_TYPE: 'IT',
      });
    } catch (error) {
      setAlertConfig({ isOpen: true, title: '에러', message: '저장 중 오류 발생' });
    }
  };

  const filteredEmployees = useMemo(() => {
    const lowerSearch = searchTerm.toLowerCase();
    return employees.filter(
      (emp) =>
        (emp.EMP_NAME || '').includes(lowerSearch) ||
        (emp.EMP_ID || '').toLowerCase().includes(lowerSearch) ||
        (emp.DEPT_NAME || '').includes(lowerSearch),
    );
  }, [searchTerm, employees]);

  return (
    <div className="flex h-screen w-full bg-gray-50 overflow-hidden font-sans text-gray-800">
      {/* [좌측] 등록 폼 */}
      <div className="w-[450px] p-8 bg-white border-r shadow-xl overflow-y-auto">
        <h2 className="text-2xl font-black mb-8 text-indigo-900 flex items-center gap-2">
          <span>👤</span> 직원 마스터 등록
        </h2>

        <form onSubmit={handleSubmit} className="space-y-5">
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                사번 *
              </label>
              <input
                type="text"
                name="EMP_ID"
                value={formData.EMP_ID}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none transition-all"
                placeholder={`E${currentYear}XXX`}
              />
            </div>
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                성명 *
              </label>
              <input
                type="text"
                name="EMP_NAME"
                value={formData.EMP_NAME}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none transition-all"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                부서명 *
              </label>
              <select
                name="DEPT_NAME"
                value={formData.DEPT_NAME}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none transition-all"
              >
                <option value="">부서 선택</option>
                {departments.map((d) => (
                  <option key={d.cd} value={d.name}>
                    {d.name}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                부서 코드
              </label>
              <input
                type="text"
                name="DEPT_CD"
                value={formData.DEPT_CD}
                readOnly
                className="w-full p-2.5 bg-gray-100 border border-gray-200 rounded-lg text-sm text-gray-500 cursor-not-allowed outline-none"
                placeholder="자동 매핑"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                로그인 ID *
              </label>
              <input
                type="text"
                name="LOGIN_ID"
                value={formData.LOGIN_ID}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                비밀번호 *
              </label>
              <input
                type="password"
                name="PASSWORD"
                value={formData.PASSWORD}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
              />
            </div>
          </div>

          <div className="space-y-4 pt-2">
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                이메일 주소
              </label>
              <input
                type="email"
                name="EMAIL"
                value={formData.EMAIL}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
              />
            </div>
            <div>
              <label className="block text-xs font-black text-gray-400 mb-1 uppercase">
                연락처 (PHONE)
              </label>
              <input
                type="text"
                name="PHONE_NO"
                value={formData.PHONE_NO}
                onChange={handleChange}
                className="w-full p-2.5 bg-gray-50 border border-gray-200 rounded-lg text-sm focus:bg-white focus:ring-2 focus:ring-indigo-400 outline-none"
                placeholder="010-0000-0000"
              />
            </div>
          </div>

          <div className="grid grid-cols-2 gap-4 pt-2">
            <div className="bg-amber-50 p-3 rounded-xl border border-amber-100 transition-all focus-within:ring-2 focus-within:ring-amber-200">
              <label className="block text-[10px] font-black text-amber-600 mb-1 uppercase tracking-tighter">
                권한 Level (Auth)
              </label>
              <select
                name="AUTH_LEVEL"
                value={formData.AUTH_LEVEL}
                onChange={handleChange}
                className="w-full bg-transparent border-none p-0 text-sm font-bold text-amber-900 focus:ring-0 outline-none cursor-pointer"
              >
                {[1, 2, 3, 5, 9].map((lv) => (
                  <option key={lv} value={lv}>
                    {lv} Level {lv === 9 ? '(Master)' : ''}
                  </option>
                ))}
              </select>
            </div>

            <div className="bg-blue-50 p-3 rounded-xl border border-blue-100 transition-all focus-within:ring-2 focus-within:ring-blue-200">
              <label className="block text-[10px] font-black text-blue-600 mb-1 uppercase tracking-tighter">
                보안 Grade (Sec)
              </label>
              <select
                name="SEC_LEVEL"
                value={formData.SEC_LEVEL}
                onChange={handleChange}
                className="w-full bg-transparent border-none p-0 text-sm font-bold text-blue-900 focus:ring-0 outline-none cursor-pointer"
              >
                <option value="1">1등급 (일반)</option>
                <option value="2">2등급 (기밀)</option>
                <option value="3">3등급 (극비)</option>
              </select>
            </div>
          </div>

          <div className="bg-gray-50 p-3 rounded-xl border border-dashed border-gray-200 mt-4">
            <p className="text-[11px] text-gray-500 leading-relaxed">
              <span className="font-bold text-gray-700">개인정보 보호 안내:</span>
              <br />본 시스템은 개인정보보호법에 의거하여 수집된 정보를 엄격히 관리합니다. 이메일,
              연락처 등 주요 정보는 DB 저장 시 암호화 처리되며, 인가된 관리자 외에는 열람이
              제한됩니다.
            </p>
          </div>
          <button
            type="submit"
            className="w-full bg-indigo-600 text-white py-4 rounded-2xl font-black text-sm hover:bg-indigo-700 shadow-xl shadow-indigo-100 transition-all active:scale-[0.98] mt-4"
          >
            새 직원 마스터 등록 완료
          </button>
        </form>
      </div>

      {/* [우측] 리스트 및 검색 */}
      <div className="flex-1 flex flex-col p-8 overflow-hidden">
        <div className="flex justify-between items-end mb-8">
          <div>
            <h2 className="text-3xl font-black text-gray-900 tracking-tighter">Master List</h2>
            <p className="text-gray-400 text-sm font-medium mt-1">
              현황: <span className="text-indigo-600">{dataType} 모드</span> 운영 중
            </p>
          </div>
          <div className="bg-white px-6 py-3 rounded-2xl shadow-sm border border-gray-100 text-center">
            <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest">Total</p>
            <p className="text-xl font-black text-indigo-600">{filteredEmployees.length}</p>
          </div>
        </div>

        <div className="mb-6 relative">
          <input
            type="text"
            placeholder="이름, 사번 또는 부서명 입력 후 Enter..."
            value={inputValue}
            onChange={(e) => setInputValue(e.target.value)}
            onKeyDown={handleKeyDown}
            className="w-full pl-14 pr-6 py-4 bg-white border-none rounded-2xl shadow-sm outline-none focus:ring-2 focus:ring-indigo-300 transition-all text-sm font-medium"
          />
          <span className="absolute left-6 top-4.5 text-xl">🔍</span>
        </div>

        <div className="flex-1 overflow-y-auto bg-white rounded-3xl shadow-sm border border-gray-100">
          <table className="w-full text-left border-collapse">
            <thead className="bg-gray-50/50 sticky top-0 z-10">
              <tr>
                <th className="p-5 text-[10px] font-black text-gray-400 uppercase">사번/성명</th>
                <th className="p-5 text-[10px] font-black text-gray-400 uppercase text-center">
                  부서 정보
                </th>
                <th className="p-5 text-[10px] font-black text-gray-400 uppercase">이메일</th>
                <th className="p-5 text-[10px] font-black text-gray-400 uppercase text-center">
                  등급
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-50">
              {filteredEmployees.length > 0 ? (
                filteredEmployees.map((emp, idx) => (
                  <tr key={idx} className="hover:bg-indigo-50/30 transition-colors group">
                    <td className="p-5">
                      <div className="text-sm font-black text-gray-800">{emp.EMP_NAME}</div>
                      <div className="text-[11px] font-mono text-gray-400">{emp.EMP_ID}</div>
                    </td>
                    <td className="p-5 text-center">
                      <div className="text-xs font-bold text-gray-700">{emp.DEPT_NAME || '-'}</div>
                      <div className="text-[10px] text-gray-400">{emp.DEPT_CD}</div>
                    </td>
                    <td className="p-5">
                      <div className="text-xs text-gray-500 font-medium">{emp.EMAIL || '-'}</div>
                    </td>
                    <td className="p-5 text-center">
                      <div className="flex justify-center gap-1.5">
                        <span className="px-2 py-0.5 bg-amber-100 text-amber-700 rounded-md text-[9px] font-black uppercase">
                          A{emp.AUTH_LEVEL}
                        </span>
                        <span
                          className={`px-2 py-0.5 rounded-md text-[9px] font-black uppercase ${emp.SEC_LEVEL >= 3 ? 'bg-red-100 text-red-600' : 'bg-blue-100 text-blue-600'}`}
                        >
                          S{emp.SEC_LEVEL}
                        </span>
                      </div>
                    </td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="4" className="p-32 text-center text-gray-300 font-medium">
                    조회 가능한 직원이 없습니다.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {alertConfig.isOpen && (
        <CustomAlert
          title={alertConfig.title}
          message={alertConfig.message}
          onConfirm={closeAlert}
          onCancel={closeAlert}
        />
      )}
    </div>
  );
};

export default AddEmployeeForm;
