import React, { useState, useCallback } from 'react';
import axios from 'axios';
import CustomAlert from './CustomAlert';

const AppLogViewer = ({ user, dataType = 'Api' }) => {
  // --- 날짜 초기값 생성 함수 ---
  const getFormattedDate = (date) => {
    return date.toISOString().split('T')[0];
  };

  const today = new Date();
  const sevenDaysAgo = new Date();
  sevenDaysAgo.setDate(today.getDate() - 7);

  const [logs, setLogs] = useState([]);
  const [loading, setLoading] = useState(false);
  const [page, setPage] = useState(0);
  const [size, setSize] = useState(15);
  const [totalPages, setTotalPages] = useState(0);

  // 1. 입력 필드용 상태: startDate와 endDate에 기본값 세팅
  const [inputFilters, setInputFilters] = useState({
    userId: '',
    moduleNm: '',
    userName: '',
    deptName: '',
    startDate: getFormattedDate(sevenDaysAgo),
    endDate: getFormattedDate(today),
  });

  const [alertConfig, setAlertConfig] = useState({
    isOpen: false,
    title: '',
    message: '',
  });

  const closeAlert = () => setAlertConfig({ ...alertConfig, isOpen: false });

  // 2. 실제 검색에 사용될 필터 상태 (초기엔 null로 두어 자동 조회 방지)
  const [appliedFilters, setAppliedFilters] = useState(null);

  const simulationData = [
    {
      logId: 'LOG-2024-001',
      logTime: '2024-05-20T10:15:30',
      userName: '김철수',
      deptName: '인사팀',
      moduleNm: 'USER_MGMT',
      actionCd: 'SELECT',
      resultStatus: 'SUCCESS',
      execTimeMs: '45',
    },
    {
      logId: 'LOG-2024-002',
      logTime: '2024-05-20T10:18:12',
      userName: '이영희',
      deptName: '개발1팀',
      moduleNm: 'API_GATEWAY',
      actionCd: 'UPDATE',
      resultStatus: 'SUCCESS',
      execTimeMs: '120',
    },
    {
      logId: 'LOG-2024-003',
      logTime: '2024-05-20T11:05:45',
      userName: '박지민',
      deptName: '영업지원',
      moduleNm: 'ORDER_SYS',
      actionCd: 'INSERT',
      resultStatus: 'FAIL',
      execTimeMs: '3500',
    },
    {
      logId: 'LOG-2024-004',
      logTime: '2024-05-21T09:00:05',
      userName: '최승우',
      deptName: '보안운영',
      moduleNm: 'AUTH_SERVER',
      actionCd: 'LOGIN',
      resultStatus: 'SUCCESS',
      execTimeMs: '12',
    },
    {
      logId: 'LOG-2024-005',
      logTime: '2024-05-21T14:22:31',
      userName: '정다은',
      deptName: '개발2팀',
      moduleNm: 'BATCH_JOB',
      actionCd: 'EXECUTE',
      resultStatus: 'SUCCESS',
      execTimeMs: '15400',
    },
    {
      logId: 'LOG-2024-006',
      logTime: '2024-05-22T13:45:10',
      userName: '강민호',
      deptName: '기획팀',
      moduleNm: 'CMS_BOARD',
      actionCd: 'DELETE',
      resultStatus: 'FAIL',
      execTimeMs: '88',
    },
    {
      logId: 'LOG-2024-007',
      logTime: '2024-05-22T15:10:00',
      userName: '윤서아',
      deptName: '디자인팀',
      moduleNm: 'ASSET_MGMT',
      actionCd: 'DOWNLOAD',
      resultStatus: 'SUCCESS',
      execTimeMs: '210',
    },
    {
      logId: 'LOG-2024-008',
      logTime: '2024-05-23T10:05:22',
      userName: '홍길동',
      deptName: '인프라팀',
      moduleNm: 'DB_MONITOR',
      actionCd: 'SELECT',
      resultStatus: 'SUCCESS',
      execTimeMs: '5',
    },
    {
      logId: 'LOG-2024-009',
      logTime: '2024-05-23T16:40:55',
      userName: '임재현',
      deptName: '고객센터',
      moduleNm: 'CRM_MAIN',
      actionCd: 'UPDATE',
      resultStatus: 'SUCCESS',
      execTimeMs: '67',
    },
    {
      logId: 'LOG-2024-010',
      logTime: '2024-05-24T11:20:18',
      userName: '송지효',
      deptName: '마케팅팀',
      moduleNm: 'AD_TRACKER',
      actionCd: 'SELECT',
      resultStatus: 'FAIL',
      execTimeMs: '1024',
    },
  ];

  // API 호출 함수
  const fetchLogs = useCallback(async (pageNum, pageSize, currentFilters) => {
    if (!currentFilters) return;

    setLoading(true);
    try {
      const response = await axios.get('http://localhost:8081/api/logs', {
        params: {
          ...currentFilters,
          page: pageNum,
          size: pageSize,
          sort: 'logTime,desc',
        },
      });
      setLogs(response.data.content);
      setTotalPages(response.data.totalPages);
      setPage(pageNum);
    } catch (error) {
      alert('로그 조회 중 오류가 발생했습니다.');
    } finally {
      setLoading(false);
    }
  }, []);

  const handleSearch = () => {
    if (!inputFilters.moduleNm) {
      setAlertConfig({
        isOpen: true,
        title: '필수입력',
        message: 'Module을 입력하세요.',
        showCancel: false,
      });
    }
    if (dataType === 'Api') {
      setAppliedFilters({ ...inputFilters });
      fetchLogs(0, size, { ...inputFilters });
    } else {
      setLogs(simulationData);
    }
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setInputFilters((prev) => ({ ...prev, [name]: value }));
  };

  const handleSizeChange = (e) => {
    if (dataType === 'Api') {
      const newSize = parseInt(e.target.value);
      setSize(newSize);
      if (appliedFilters) {
        fetchLogs(0, newSize, appliedFilters);
      }
    }
  };

  const goToPage = (pageNum) => {
    if (dataType === 'Api') {
      if (pageNum >= 0 && pageNum < totalPages) {
        fetchLogs(pageNum, size, appliedFilters);
      }
    }
  };

  return (
    <div style={containerStyle}>
      {/* 상단 헤더 및 행 수 조절 */}
      <header style={headerStyle}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h2 style={titleStyle}>
              🚀 <span style={{ color: '#3182ce' }}>System</span> App Log
            </h2>
            <p style={subTitleStyle}>날짜 범위가 최근 7일로 기본 설정되었습니다.</p>
          </div>
          <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
            <label style={labelStyle}>Rows:</label>
            <select style={selectStyle} value={size} onChange={handleSizeChange}>
              <option value={10}>10</option>
              <option value={15}>15</option>
              <option value={30}>30</option>
              <option value={50}>50</option>
            </select>
          </div>
        </div>
      </header>

      {/* 필터 영역 */}
      <div style={cardStyle}>
        <div style={filterGridStyle}>
          <div style={inputGroupStyle}>
            <label style={labelStyle}>Module</label>
            <input
              name="moduleNm"
              style={inputStyle}
              value={inputFilters.moduleNm}
              onChange={handleInputChange}
              placeholder="모듈명"
            />
          </div>
          <div style={inputGroupStyle}>
            <label style={labelStyle}>Date Range</label>
            <div style={{ display: 'flex', gap: '5px' }}>
              <input
                type="date"
                name="startDate"
                style={inputStyle}
                value={inputFilters.startDate}
                onChange={handleInputChange}
              />
              <input
                type="date"
                name="endDate"
                style={inputStyle}
                value={inputFilters.endDate}
                onChange={handleInputChange}
              />
            </div>
          </div>
          <div style={inputGroupStyle}> </div>
          <button onClick={handleSearch} style={searchBtnStyle}>
            Search Logs
          </button>
        </div>
      </div>

      {/* 데이터 테이블 */}
      <div style={{ ...cardStyle, padding: '0', overflow: 'hidden' }}>
        <div style={scrollContainerStyle}>
          <table style={tableStyle}>
            <thead style={stickyHeaderStyle}>
              <tr style={theadRowStyle}>
                <th style={thStyle}>ID</th>
                <th style={thStyle}>Timestamp</th>
                <th style={thStyle}>User</th>
                <th style={thStyle}>Dept</th>
                <th style={thStyle}>Module</th>
                <th style={thStyle}>Action</th>
                <th style={thStyle}>Status</th>
                <th style={thStyle}>Exec</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan="7" style={emptyTdStyle}>
                    로딩 중...
                  </td>
                </tr>
              ) : logs.length > 0 ? (
                logs.map((log) => (
                  <tr key={log.logId} style={trStyle}>
                    <td style={tdStyle}>
                      <span style={idBadgeStyle}>{log.logId}</span>
                    </td>
                    <td style={tdStyle}>{log.logTime?.replace('T', ' ').substring(0, 19)}</td>
                    <td style={tdStyle}>{log.userName}</td>
                    <td style={tdStyle}>{log.deptName}</td>
                    <td style={{ ...tdStyle, fontWeight: '700' }}>{log.moduleNm}</td>
                    <td style={tdStyle}>
                      <span style={actionBadgeStyle}>{log.actionCd}</span>
                    </td>
                    <td style={tdStyle}>
                      <span
                        style={log.resultStatus === 'FAIL' ? failBadgeStyle : successBadgeStyle}
                      >
                        {log.resultStatus}
                      </span>
                    </td>
                    <td style={tdStyle}>{log.execTimeMs}ms</td>
                  </tr>
                ))
              ) : (
                <tr>
                  <td colSpan="7" style={emptyTdStyle}>
                    {appliedFilters ? '결과가 없습니다.' : '조건 확인 후 Search Logs를 눌러주세요.'}
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>

      {/* 페이징 */}
      {totalPages > 0 && (
        <div style={paginationStyle}>
          <button onClick={() => goToPage(page - 1)} disabled={page === 0} style={navBtnStyle}>
            Prev
          </button>
          {Array.from({ length: totalPages }, (_, i) => i)
            .filter((i) => i >= page - 2 && i <= page + 2)
            .map((i) => (
              <button
                key={i}
                onClick={() => goToPage(i)}
                style={{
                  ...pageBtnStyle,
                  backgroundColor: page === i ? '#3182ce' : '#fff',
                  color: page === i ? '#fff' : '#4a5568',
                }}
              >
                {i + 1}
              </button>
            ))}
          <button
            onClick={() => goToPage(page + 1)}
            disabled={page === totalPages - 1}
            style={navBtnStyle}
          >
            Next
          </button>
        </div>
      )}
      {alertConfig.isOpen && (
        <CustomAlert
          title={alertConfig.title}
          message={alertConfig.message}
          onConfirm={closeAlert}
          onCancel={closeAlert}
        />
      )}
    </div>
  );
};

// --- 스타일 객체 (기존과 동일) ---
const containerStyle = {
  padding: '30px 40px',
  backgroundColor: '#f7fafc',
  height: 'calc(100vh - 102px)',
  fontFamily: 'sans-serif',
};
const headerStyle = { marginBottom: '20px' };
const titleStyle = { fontSize: '24px', fontWeight: '800', margin: '0' };
const subTitleStyle = { color: '#718096', fontSize: '13px', marginTop: '5px' };
const cardStyle = {
  backgroundColor: '#fff',
  boxShadow: '0 2px 10px rgba(0,0,0,0.05)',
  padding: '20px',
  marginBottom: '20px',
};
const filterGridStyle = {
  display: 'grid',
  gridTemplateColumns: '1fr 1.5fr 1fr auto',
  gap: '15px',
  alignItems: 'flex-end',
};
const inputGroupStyle = { display: 'flex', flexDirection: 'column', gap: '5px' };
const labelStyle = { fontSize: '12px', fontWeight: 'bold', color: '#4a5568' };
const inputStyle = {
  padding: '8px 12px',
  borderRadius: '6px',
  border: '1px solid #e2e8f0',
  fontSize: '14px',
};
const selectStyle = {
  padding: '6px 10px',
  borderRadius: '6px',
  border: '1px solid #e2e8f0',
  cursor: 'pointer',
};
const searchBtnStyle = {
  padding: '10px 20px',
  backgroundColor: '#3182ce',
  color: '#fff',
  border: 'none',
  borderRadius: '8px',
  cursor: 'pointer',
  fontWeight: 'bold',
};
const scrollContainerStyle = {
  maxHeight: '506px',
  overflowY: 'auto',
  border: '1px solid #edf2f7',
  borderRadius: '0 0 12px 12px',
};
const tableStyle = { width: '100%', borderCollapse: 'collapse', textAlign: 'left' };
const stickyHeaderStyle = { position: 'sticky', top: 0, zIndex: 1, backgroundColor: '#f8fafc' };
const thStyle = {
  padding: '12px 15px',
  fontSize: '12px',
  color: '#718096',
  borderBottom: '2px solid #edf2f7',
};
const theadRowStyle = { backgroundColor: '#f8fafc' };
const trStyle = { borderBottom: '1px solid #edf2f7' };
const tdStyle = { padding: '12px 15px', fontSize: '14px', color: '#2d3748' };
const idBadgeStyle = { color: '#a0aec0', fontSize: '12px' };
const actionBadgeStyle = {
  padding: '2px 6px',
  borderRadius: '4px',
  backgroundColor: '#edf2f7',
  fontSize: '11px',
};
const successBadgeStyle = {
  color: '#2f855a',
  backgroundColor: '#c6f6d5',
  padding: '2px 8px',
  borderRadius: '4px',
  fontSize: '11px',
  fontWeight: 'bold',
};
const failBadgeStyle = {
  color: '#c53030',
  backgroundColor: '#fed7d7',
  padding: '2px 8px',
  borderRadius: '4px',
  fontSize: '11px',
  fontWeight: 'bold',
};

const emptyTdStyle = { padding: '80px', textAlign: 'center', color: '#a0aec0' };
const paginationStyle = {
  marginTop: '20px',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  gap: '8px',
};
const pageBtnStyle = {
  width: '34px',
  height: '34px',
  borderRadius: '6px',
  border: '1px solid #e2e8f0',
  cursor: 'pointer',
  fontWeight: 'bold',
};
const navBtnStyle = {
  padding: '6px 12px',
  borderRadius: '6px',
  border: '1px solid #e2e8f0',
  cursor: 'pointer',
  backgroundColor: '#fff',
  fontSize: '13px',
};

export default AppLogViewer;
