import React, { useMemo, useState } from 'react';
import {
  useReactTable,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  flexRender,
  createColumnHelper,
} from '@tanstack/react-table';

const Output = ({ data }) => {
  const [sorting, setSorting] = useState([]);
  const columnHelper = createColumnHelper();

  // 1. 새로운 데이터 구조에 맞춘 컬럼 정의
  const columns = useMemo(() => {
    if (!data || data.length === 0) return [];

    // 1. 현재 데이터에 존재하는 모든 키(Key) 추출
    const availableKeys = Object.keys(data[0]);

    // 2. 전체 정의 가능한 컬럼 명세 (Full Specification)
    const columnSpecs = [
      { key: 'line', header: 'Line' },
      { key: 'process', header: 'Process' },
      { key: 'partid', header: 'Part ID' },
      { key: 'step', header: 'Step' },
      { key: 'equip', header: 'Equipment' },
      { key: 'etarea', header: 'ET Area' },
      { key: 'lotgroup', header: 'Lot Group' },
      { key: 'lottype', header: 'Lot Type' },
      { key: 'lot_id', header: 'Lot ID' },
      { key: 'wafer_id', header: 'Wafer ID' },
      { key: 'y1item', header: 'Item Name' },
      { key: 'item', header: 'Item Name' },
      {
        key: 'value',
        header: 'Value',
        cell: (info) => {
          const val = info.getValue();
          return typeof val === 'number' ? val.toFixed(2) : val;
        },
      },
      {
        key: 'tkin_time',
        header: 'In Time',
        cell: (info) => <span style={{ whiteSpace: 'nowrap' }}>{info.getValue()}</span>,
      },
      {
        key: 'tkout_time',
        header: 'Out Time',
        cell: (info) => <span style={{ whiteSpace: 'nowrap' }}>{info.getValue()}</span>,
      },
    ];

    // 3. 데이터에 존재하는 키만 필터링하여 컬럼 생성
    return columnSpecs
      .filter((spec) => availableKeys.includes(spec.key))
      .map((spec) =>
        columnHelper.accessor(spec.key, {
          header: spec.header,
          cell: spec.cell || ((info) => info.getValue()), // 별도 cell 정의 없으면 기본값
        }),
      );
  }, [data, columnHelper]);

  // 2. 테이블 인스턴스 생성
  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageSize: 20 } }, // 기본 노출 행 수 상향
  });

  return (
    <div style={{ padding: '10px', backgroundColor: '#fff', borderRadius: '8px' }}>
      <div style={{ marginBottom: '10px', fontSize: '13px', color: '#666' }}>
        Total Records: <strong>{data.length.toLocaleString()}</strong> rows
      </div>

      <div style={{ overflowX: 'auto', border: '1px solid #ddd', borderRadius: '4px' }}>
        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px' }}>
          <thead style={{ backgroundColor: '#f1f3f5', borderBottom: '2px solid #dee2e6' }}>
            {table.getHeaderGroups().map((headerGroup) => (
              <tr key={headerGroup.id}>
                {headerGroup.headers.map((header) => (
                  <th
                    key={header.id}
                    onClick={header.column.getToggleSortingHandler()}
                    style={{
                      padding: '10px',
                      textAlign: 'left',
                      cursor: 'pointer',
                      borderRight: '1px solid #dee2e6',
                      whiteSpace: 'nowrap',
                      backgroundColor: header.column.getIsSorted() ? '#e9ecef' : 'inherit',
                    }}
                  >
                    {flexRender(header.column.columnDef.header, header.getContext())}
                    {{ asc: ' 🔼', desc: ' 🔽' }[header.column.getIsSorted()] ?? null}
                  </th>
                ))}
              </tr>
            ))}
          </thead>
          <tbody>
            {table.getRowModel().rows.map((row) => (
              <tr
                key={row.id}
                style={{
                  borderBottom: '1px solid #eee',
                  backgroundColor: row.index % 2 === 0 ? '#fff' : '#fcfcfc', // Zebra Stripe
                }}
              >
                {row.getVisibleCells().map((cell) => (
                  <td
                    key={cell.id}
                    style={{ padding: '8px 10px', borderRight: '1px solid #f1f1f1' }}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </td>
                ))}
              </tr>
            ))}
          </tbody>
        </table>
      </div>

      {/* 페이지네이션 컨트롤 */}
      <div
        style={{
          marginTop: '15px',
          display: 'flex',
          alignItems: 'center',
          gap: '15px',
          justifyContent: 'center',
        }}
      >
        <div style={{ display: 'flex', gap: '5px' }}>
          <button
            onClick={() => table.setPageIndex(0)}
            disabled={!table.getCanPreviousPage()}
            style={navButtonStyle}
          >
            처음
          </button>
          <button
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            style={navButtonStyle}
          >
            이전
          </button>
          <button
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            style={navButtonStyle}
          >
            다음
          </button>
          <button
            onClick={() => table.setPageIndex(table.getPageCount() - 1)}
            disabled={!table.getCanNextPage()}
            style={navButtonStyle}
          >
            끝
          </button>
        </div>

        <span style={{ fontSize: '13px' }}>
          Page <strong>{table.getState().pagination.pageIndex + 1}</strong> of{' '}
          <strong>{table.getPageCount()}</strong>
        </span>

        <select
          value={table.getState().pagination.pageSize}
          onChange={(e) => table.setPageSize(Number(e.target.value))}
          style={{ padding: '4px', borderRadius: '4px', fontSize: '12px' }}
        >
          {[20, 50, 100, 500].map((pageSize) => (
            <option key={pageSize} value={pageSize}>
              {pageSize}개씩 보기
            </option>
          ))}
        </select>
      </div>
    </div>
  );
};

const navButtonStyle = {
  padding: '4px 10px',
  cursor: 'pointer',
  borderRadius: '4px',
  border: '1px solid #ccc',
  backgroundColor: '#fff',
  fontSize: '12px',
};

export default Output;
