import React, { useState, useRef, useCallback, useEffect } from 'react';
import { generateCondition } from '../utils/ConditionGenerator';
import ListSelector from '../controls/ListSelector';
import LineSelector from '../controls/LineSelector';
import SetupModal from '../utils/SetupWaferGeometry';
import Gallery from './Gallery-Map';
import CustomAlert from '../utils/CustomAlert';
import { captureLog } from '../utils/logService';

// 1. 수직 계층 구조 (상하 관계)
const VERTICAL_ORDER = ['line', 'process', 'product', 'lottype', 'step'];
const LEAF_ITEMS = ['item', 'lotwafer'];

const LayoutMap = ({ user, dataType = 'Gen', module = 'EDSMAP' }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [sidebarWidth, setSidebarWidth] = useState(600);
  const [isCollapsed, setIsCollapsed] = useState(false);
  const setupBtnRef = useRef(null);
  const isResizingWidth = useRef(false);
  const [waferInfo, setWaferInfo] = useState('Information...');
  const [drawParams, setDrawParams] = useState(null);

  // 1. 상태 통합 관리
  const [mapSettings, setMapSettings] = useState({
    waferSize: 300000,
    waferEdge: 3000,
    dieSizeX: 9000,
    dieSizeY: 9000,
    scribeSize: 200,
    columnCount: 3,
    mapType: 'EDS',
    realSize: false,
  });

  const [filterStates, setFilterStates] = useState({
    line: { filter: '', selected: [], options: [], fromDate: '', toDate: '' },
    process: { filter: '', selected: [], options: [] },
    product: { filter: '', selected: [], options: [] },
    lottype: { filter: '', selected: [], options: [] },
    step: { filter: '', selected: [], options: [] },
    item: { filter: '', selected: [], options: [] },
    lotwafer: { filter: '', selected: [], options: [] },
  });

  const [alertConfig, setAlertConfig] = useState({
    isOpen: false,
    title: '',
    message: '',
  });

  // [추가] module 변경 시 mapType 초기화 로직
  useEffect(() => {
    let defaultMapType = 'EDS';
    if (module === 'EDSMAP') {
      defaultMapType = 'EDS';
    } else if (module === 'DEFECTMAP') {
      defaultMapType = 'DEFECT';
    } else {
      defaultMapType = 'EDS';
    }

    setMapSettings((prev) => ({
      ...prev,
      mapType: defaultMapType,
    }));
  }, [module]);

  // 알림창을 여는 통합 함수
  const showAlert = (type, category) => {
    const configs = {
      selectionRequired: {
        title: '선택 필요',
        message: `상위 항목인 [${category}]을(를) 먼저 선택해야 합니다.`,
      },
      applyRequired: {
        title: '필수 항목 선택 누락',
        message: `필수 항목인 [${category}]을(를) 선택해주세요.`,
      },
    };

    setAlertConfig({
      isOpen: true,
      ...configs[type], // 선택한 타입의 데이터를 복사
    });
  };

  const closeAlert = () => setAlertConfig({ ...alertConfig, isOpen: false });

  // 2. 핸들러 (통합)
  const handleSettingChange = (e) => {
    const { name, value, type, checked } = e.target;
    setMapSettings((prev) => ({
      ...prev,
      [name]: type === 'checkbox' ? checked : name === 'mapType' ? value : Number(value),
    }));
  };

  /**
   * 계층 구조 하위 항목 초기화 로직
   * 상위 카테고리가 변경되면 그 아래의 모든 옵션과 선택값을 비웁니다.
   */
  const clearLowerSelectors = (currentCategory) => {
    const currentIndex = VERTICAL_ORDER.indexOf(currentCategory);
    let targetsToClear = [];

    if (currentIndex !== -1) {
      // 1. 수직 계층에서 현재 인덱스 이후의 모든 카테고리
      const lowerVertical = VERTICAL_ORDER.slice(currentIndex + 1);
      // 2. 최하위 동일 레벨(형제) 항목들 포함
      targetsToClear = [...lowerVertical, ...LEAF_ITEMS];
    } else if (LEAF_ITEMS.includes(currentCategory)) {
      // 최하위 레벨(item, lot) 변경 시에는 서로에게 영향을 주지 않음
      targetsToClear = [];
    }

    if (targetsToClear.length === 0) return;

    // 통합 상태 업데이트
    setFilterStates((prev) => {
      const newState = { ...prev };
      targetsToClear.forEach((cat) => {
        newState[cat] = {
          ...prev[cat],
          filter: '', // 필터 텍스트 초기화
          selected: [], // 선택된 값 초기화
          options: [], // 불러온 목록 초기화
        };
      });
      return newState;
    });
  };

  /**
   * 데이터 조회 핸들러
   * fetch 버튼(🔍) 클릭 시 실행
   */
  const fetchOptions = async (category) => {
    try {
      // [추가] 상위 필수 항목 검증 로직
      const currentIndex = VERTICAL_ORDER.indexOf(category);
      const isLeaf = LEAF_ITEMS.includes(category);

      // 검증 대상 설정
      let requiredFields = [];
      if (currentIndex > 0) {
        // VERTICAL_ORDER 내의 상위 항목들
        requiredFields = VERTICAL_ORDER.slice(0, currentIndex);
      } else if (isLeaf) {
        // item, lot 조회 시에는 VERTICAL_ORDER 전체가 상위 필수 계층
        requiredFields = VERTICAL_ORDER;
      }

      // 'lottype'은 검증에서 제외 (선택 사항)
      const skipFields = ['lottype'];

      for (const field of requiredFields) {
        if (!skipFields.includes(field)) {
          if (!filterStates[field].selected || filterStates[field].selected.length === 0) {
            const labels = { line: 'Line', process: 'Process', product: 'Product', step: 'Step' };
            showAlert('selectionRequired', labels[field] || field);
            return;
          }
        }
      }

      // 1. 하위 항목 초기화 선행
      clearLowerSelectors(category);

      // 2. 현재 카테고리의 필터 입력값 가져오기
      const keyword = filterStates[category].filter;

      // 3. API 대용 데이터 생성 (ConditionGenerator)
      const data = generateCondition(category, keyword);

      // 4. 해당 카테고리의 options 목록만 업데이트
      setFilterStates((prev) => ({
        ...prev,
        [category]: {
          ...prev[category],
          options: data,
        },
      }));
    } catch (err) {
      console.error(`${category} 데이터 로드 실패:`, err);
    }
  };

  const handleFilterChange = (category, value) => {
    setFilterStates((prev) => ({ ...prev, [category]: { ...prev[category], filter: value } }));
  };

  const handleSelectChange = (e) => {
    const { name, options } = e.target;

    // 추가: 선택이 바뀌면 하위 데이터 정합성을 위해 하위 옵션들을 초기화
    clearLowerSelectors(name);

    const values = Array.from(options)
      .filter((opt) => opt.selected)
      .map((opt) => opt.value);

    setFilterStates((prev) => ({
      ...prev,
      [name]: { ...prev[name], selected: values },
    }));
  };

  const handleApplySearch = () => {
    // [추가] 최종 검색 필수 항목 검증 (Line, Process, Product, Step, Item, Lot)
    const finalRequired = ['line', 'process', 'product', 'step', 'item', 'lotwafer'];
    const labels = {
      line: 'Line',
      process: 'Process',
      product: 'Product',
      step: 'Step',
      item: 'Item',
      lotwafer: 'lotwafer',
    };

    for (const key of finalRequired) {
      if (!filterStates[key].selected || filterStates[key].selected.length === 0) {
        showAlert('applyRequired', labels[key]);
        return; // 검증 실패 시 실행 중단
      }
    }

    // 검증 통과 시 상태 업데이트
    setDrawParams({
      ...mapSettings,
      filters: {
        line: filterStates.line.selected,
        dateRange: { from: filterStates.line.fromDate, to: filterStates.line.toDate },
        process: filterStates.process.selected,
        product: filterStates.product.selected,
        lottype: filterStates.lottype.selected,
        step: filterStates.step.selected,
        item: filterStates.item.selected,
        lotwafer: filterStates.lotwafer.selected,
      },
    });
  };

  // --- [NEW] 높이 조절 상태 ---
  const [gridHeights, setGridHeights] = useState({
    first: 140,
    second: 140,
    third: 140,
    lot: 150,
  });

  // --- [NEW] 높이 조절 핸들러 ---
  const activeResizer = useRef(null);

  const startVerticalResize = (e, section) => {
    activeResizer.current = { section, startY: e.clientY, startHeight: gridHeights[section] };
    document.addEventListener('mousemove', handleVerticalResize);
    document.addEventListener('mouseup', stopVerticalResize);
    document.body.style.cursor = 'row-resize';
  };

  const handleVerticalResize = useCallback((e) => {
    if (!activeResizer.current) return;
    const { section, startY, startHeight } = activeResizer.current;
    const diff = e.clientY - startY;
    const newHeight = Math.max(80, startHeight + diff); // 최소 높이 80px

    setGridHeights((prev) => ({ ...prev, [section]: newHeight }));
  }, []);

  const stopVerticalResize = () => {
    activeResizer.current = null;
    document.removeEventListener('mousemove', handleVerticalResize);
    document.removeEventListener('mouseup', stopVerticalResize);
    document.body.style.cursor = 'default';
  };

  // Resize 로직 (동일)
  const startResizing = useCallback(() => {
    isResizingWidth.current = true;
    document.addEventListener('mousemove', resize);
    document.addEventListener('mouseup', stopResizing);
  }, []);
  const stopResizing = useCallback(() => {
    isResizingWidth.current = false;
    document.removeEventListener('mousemove', resize);
    document.removeEventListener('mouseup', stopResizing);
  }, []);
  const resize = useCallback((e) => {
    if (isResizingWidth.current) {
      const newWidth = e.clientX;
      if (newWidth > 300 && newWidth < 800) setSidebarWidth(newWidth);
    }
  }, []);

  const VerticalSplitter = ({ onMouseDown }) => (
    <div
      onMouseDown={onMouseDown}
      style={{
        height: '6px',
        cursor: 'row-resize',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        margin: '2px 0',
        transition: 'background 0.2s',
      }}
      onMouseEnter={(e) => (e.target.style.backgroundColor = '#e2e8f0')}
      onMouseLeave={(e) => (e.target.style.backgroundColor = 'transparent')}
    >
      <div
        style={{ width: '30px', height: '2px', backgroundColor: '#cbd5e1', borderRadius: '2px' }}
      />
    </div>
  );

  return (
    <div style={containerStyle}>
      <div
        style={{
          ...sidebarStyle,
          width: isCollapsed ? '0px' : `${sidebarWidth}px`,
          padding: isCollapsed ? '0' : '12px',
          overflow: isCollapsed ? 'hidden' : 'visible',
        }}
      >
        {!isCollapsed && (
          <div
            style={{ display: 'flex', flexDirection: 'column', height: '100%', minWidth: '350px' }}
          >
            <div style={headerContainerStyle}>
              <h3 style={{ margin: 0, fontSize: '14px' }}>Search Filters</h3>
              <button ref={setupBtnRef} onClick={() => setIsModalOpen(true)} style={setupBtnStyle}>
                ⚙️ Wafer Geometry
              </button>
            </div>

            <div style={{ ...scrollAreaStyle, position: 'relative' }}>
              <div style={{ ...firstFilterGridStyle, height: `${gridHeights.first}px` }}>
                <LineSelector
                  style={{ height: '100%' }}
                  category="line"
                  label="Line"
                  filterValue={filterStates.line.filter}
                  options={filterStates.line.options}
                  selectedValues={filterStates.line.selected}
                  onFilterChange={handleFilterChange}
                  onSelectChange={handleSelectChange}
                  onFetch={fetchOptions} // [추가] 조회 함수 연결
                  onDateChange={(d) =>
                    setFilterStates((p) => ({
                      ...p,
                      line: { ...p.line, fromDate: d.from, toDate: d.to },
                    }))
                  }
                  datePickerHeight="25px"
                  dateFontSize="10px"
                  isMulti={false}
                />
                {['process'].map((cat) => (
                  <ListSelector
                    style={{ height: '100%' }}
                    key={cat}
                    label={cat}
                    category={cat}
                    filterValue={filterStates[cat].filter}
                    options={filterStates[cat].options}
                    selectedValues={filterStates[cat].selected}
                    onFilterChange={handleFilterChange}
                    onSelectChange={handleSelectChange}
                    onFetch={fetchOptions} // [추가] 조회 함수 연결
                  />
                ))}
              </div>

              <VerticalSplitter onMouseDown={(e) => startVerticalResize(e, 'first')} />

              <div style={{ ...secondFilterGridStyle, height: `${gridHeights.second}px` }}>
                {['product', 'lottype'].map((cat) => (
                  <ListSelector
                    style={{ height: '100%' }}
                    key={cat}
                    label={cat}
                    category={cat}
                    filterValue={filterStates[cat].filter}
                    options={filterStates[cat].options}
                    selectedValues={filterStates[cat].selected}
                    onFilterChange={handleFilterChange}
                    onSelectChange={handleSelectChange}
                    onFetch={fetchOptions} // [추가] 조회 함수 연결
                  />
                ))}
              </div>

              <VerticalSplitter onMouseDown={(e) => startVerticalResize(e, 'second')} />

              <div style={{ ...filterGridStyle, height: `${gridHeights.third}px` }}>
                {['step', 'item'].map((cat) => (
                  <ListSelector
                    style={{ height: '100%' }}
                    key={cat}
                    label={cat}
                    category={cat}
                    filterValue={filterStates[cat].filter}
                    options={filterStates[cat].options}
                    selectedValues={filterStates[cat].selected}
                    onFilterChange={handleFilterChange}
                    onSelectChange={handleSelectChange}
                    onFetch={fetchOptions} // [추가] 조회 함수 연결
                  />
                ))}
              </div>

              <VerticalSplitter onMouseDown={(e) => startVerticalResize(e, 'third')} />

              <div
                className="lot-wafer"
                style={{ height: `${gridHeights.lot}px`, display: 'flex', flexDirection: 'column' }}
              >
                <ListSelector
                  label="Lot.Wafer"
                  category="lotwafer"
                  labelWidth="60px"
                  filterValue={filterStates.lotwafer.filter}
                  options={filterStates.lotwafer.options}
                  selectedValues={filterStates.lotwafer.selected}
                  onFilterChange={handleFilterChange}
                  onSelectChange={handleSelectChange}
                  onFetch={fetchOptions} // [추가] 조회 함수 연결
                />
              </div>

              <VerticalSplitter onMouseDown={(e) => startVerticalResize(e, 'lot')} />

              {/* 3. 하단 정렬 영역 (Parameters + Buttons) */}
              <div style={bottomControlSectionStyle}>
                <div style={paramSectionStyle}>
                  <div style={paramGridStyle}>
                    {/* Columns 설정 */}
                    <div style={inputBox}>
                      <label style={miniLabelStyle}>Columns</label>
                      <select
                        name="columnCount"
                        value={mapSettings.columnCount}
                        onChange={handleSettingChange}
                        style={sideSelectStyle}
                      >
                        {[1, 2, 3, 4, 5, 10].map((v) => (
                          <option key={v} value={v}>
                            {v}
                          </option>
                        ))}
                      </select>
                    </div>

                    {/* Map Type 설정 */}
                    <div style={inputBox}>
                      <label style={miniLabelStyle}>Map Type</label>
                      <select
                        name="mapType"
                        value={mapSettings.mapType}
                        onChange={handleSettingChange}
                        style={sideSelectStyle}
                      >
                        {module === 'EDSMAP' ? (
                          <>
                            <option value="EDS">EDS</option>
                            <option value="MEASURE">MEASURE</option>
                            <option value="MEASURE-Contour">MEASURE-Contour</option>
                          </>
                        ) : module === 'DEFECTMAP' ? (
                          <>
                            <option value="DEFECT">DEFECT</option>
                          </>
                        ) : (
                          <>
                            <option value="METRO-CD">METRO-CD</option>
                            <option value="METRO-CD-Contour">METRO-CD-Contour</option>
                          </>
                        )}
                      </select>
                    </div>

                    {/* Defect 옵션 (조건부) */}
                    {mapSettings.mapType === 'DEFECT' && (
                      <div style={inputBoxCheck}>
                        <label style={sideCheckboxLabel}>
                          <input
                            name="realSize"
                            type="checkbox"
                            checked={mapSettings.realSize}
                            onChange={handleSettingChange}
                            style={checkboxInputStyle}
                          />
                          <span>Real Size Defect</span>
                        </label>
                      </div>
                    )}
                  </div>
                </div>
                <div style={buttonAreaStyle}>
                  <button style={searchButtonStyle} onClick={handleApplySearch}>
                    ( WaferCount = PRODUCT * STEP * ITEM * LOT.WAFER ) Draw Wafer Maps
                  </button>
                </div>
                <div style={waferInfoStyle}>{waferInfo}</div>
              </div>
            </div>
          </div>
        )}
      </div>

      <div style={splitterWrapperStyle} onMouseDown={startResizing}>
        <div style={splitterLineStyle} />
        <button onClick={() => setIsCollapsed(!isCollapsed)} style={toggleBtnStyle}>
          {isCollapsed ? '▶' : '◀'}
        </button>
      </div>

      <div style={mainAreaStyle}>
        {drawParams ? (
          <Gallery
            user={user}
            module={module}
            params={drawParams}
            dataType={dataType}
            onInfoUpdate={setWaferInfo}
          />
        ) : (
          <div style={emptyStateStyle}>필터를 설정하고 Draw Wafer Maps를 클릭하세요.</div>
        )}
      </div>

      {isModalOpen && (
        <SetupModal
          anchorRef={setupBtnRef}
          initialSettings={mapSettings}
          onClose={() => setIsModalOpen(false)}
          onApply={(val) => {
            setMapSettings((prev) => ({ ...prev, ...val }));
            setIsModalOpen(false);
          }}
        />
      )}
      {alertConfig.isOpen && (
        <CustomAlert
          title={alertConfig.title}
          message={alertConfig.message}
          onConfirm={closeAlert}
          onCancel={closeAlert}
        />
      )}
    </div>
  );
};

const paramSectionStyle = {
  padding: '6px 10px',
  backgroundColor: '#f1f5f9',
  borderRadius: '6px',
  border: '1px solid #e2e8f0',
  marginBottom: '8px',
};

const paramGridStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(3, 1fr)', // 정확히 3등분 반복
  gap: '8px', // 열 사이 간격
  alignItems: 'center',
};

const inputBox = {
  display: 'flex',
  alignItems: 'center',
  gap: '4px',
  width: '100%', // 열 내부 꽉 채우기
};

const miniLabelStyle = {
  fontSize: '11px',
  fontWeight: '700',
  color: '#64748b',
  whiteSpace: 'nowrap', // 라벨 줄바꿈 방지
  flexShrink: 0, // 라벨 너비 유지
};

const sideSelectStyle = {
  width: '100%', // 부모 너비에 맞춤
  height: '22px', // 70% 수준으로 더 축소
  padding: '0 2px',
  fontSize: '11px',
  borderRadius: '4px',
  border: '1px solid #cbd5e1',
  backgroundColor: '#ffffff',
  outline: 'none',
  cursor: 'pointer',
};

const sideCheckboxLabel = {
  display: 'flex',
  alignItems: 'center',
  gap: '3px',
  fontSize: '10px',
  color: '#475569',
  cursor: 'pointer',
  whiteSpace: 'nowrap',
};

const inputBoxCheck = {
  display: 'flex',
  alignItems: 'center',
  padding: '2px 0 0 73px', // 라벨 너비만큼 밀어서 정렬
};

const checkboxInputStyle = {
  width: '13px',
  height: '13px',
  cursor: 'pointer',
};

// --- New/Updated Styles ---
const waferInfoStyle = {
  fontSize: '11px',
  color: '#666',
  marginTop: '10px',
  padding: '5px',
  background: '#eee',
};
const containerStyle = {
  display: 'flex',
  height: 'calc(100vh - 102px)',
  backgroundColor: '#f4f7f9',
  overflow: 'hidden',
};
const sidebarStyle = {
  flexShrink: 0,
  backgroundColor: '#fff',
  borderRight: '1px solid #dee2e6',
  display: 'flex',
  flexDirection: 'column',
  position: 'relative',
  transition: 'all 0.3s ease',
};
const firstFilterGridStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(2, 1fr)', // 1행: 5개 항목
  gap: '17px',
  marginBottom: '3px',
};
const secondFilterGridStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(2, 1fr)', // 1행: 5개 항목
  gap: '17px',
  marginBottom: '3px',
};

const filterGridStyle = {
  display: 'grid',
  gridTemplateColumns: 'repeat(2, 1fr)', // 1행: 5개 항목
  gap: '17px',
  marginBottom: '3px',
};

const scrollAreaStyle = {
  flex: 1, // 남는 공간을 모두 차지하여 아래 섹션을 바닥으로 밀어냄
  overflowY: 'auto',
  paddingRight: '8px',
  marginBottom: '10px',
};
const splitterWrapperStyle = {
  width: '8px',
  cursor: 'col-resize',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  backgroundColor: '#f1f3f5',
  position: 'relative',
};
const splitterLineStyle = { width: '1px', height: '100%', backgroundColor: '#dee2e6' };
const toggleBtnStyle = {
  position: 'absolute',
  width: '16px',
  height: '32px',
  backgroundColor: '#fff',
  border: '1px solid #ddd',
  borderRadius: '4px',
  cursor: 'pointer',
  zIndex: 10,
  fontSize: '10px',
};
const mainAreaStyle = {
  flexGrow: 1,
  position: 'relative',
  backgroundColor: '#f8fafc',
  overflow: 'hidden',
};
const emptyStateStyle = {
  display: 'flex',
  height: '100%',
  alignItems: 'center',
  justifyContent: 'center',
  color: '#94a3b8',
};
const headerContainerStyle = {
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  marginBottom: '12px',
  borderBottom: '2px solid #3182ce',
  paddingBottom: '8px',
};
const setupBtnStyle = {
  padding: '4px 8px',
  fontSize: '11px',
  cursor: 'pointer',
  backgroundColor: '#fff',
  border: '1px solid #3182ce',
  borderRadius: '4px',
  color: '#3182ce',
};
const bottomControlSectionStyle = {
  flexShrink: 0, // 내용에 맞게 크기 유지
  borderTop: '1px solid #e2e8f0',
  paddingTop: '5px',
  backgroundColor: '#fff',
};

