import axios from 'axios';

export const captureLog = async (user, moduleNm, actionCd) => {
  try {
    await axios.post('http://localhost:8081/api/logs/capture', {
      userId: user.empId || 'ANONYMOUS',
      userName: user.empName,
      deptName: user.deptName,
      moduleNm: moduleNm,
      actionCd: actionCd, // 'SEARCH', 'RUN', 'DRAW', 'EXPORT' 등
      screenUrl: window.location.pathname,
    });
  } catch (err) {
    console.error('Log capture failed', err);
  }
};
