import { useState, useEffect } from 'react';
import './App.css';
import LoginPage from './Login';
import HeaderMenu from './components/Header-Menu';
import LayoutMonitoring from './components/monitoring/Layout-Monitoring';
import LayoutEquivalence from './components/analysis/Layout-Equivalence';
import LayoutSleuth from './components/analysis/Layout-Sleuth';
import LayoutMap from './components/mapview/Layout-Map';
import LayoutMetro from './components/mapview/Layout-Metro';
import LayoutMassive from './components/mapview/Layout-Massive';
import AddEmployeeForm from './components/utils/AddEmployeeForm';
import EmployeeManagement from './components/utils/EmployeeManagement';
import AppLogViewer from './components/utils/AppLogViewer';
import MainPage from './components/MainPage';
import AboutProject from './components/AboutProject';
import Copyrights from './components/Copyrights';
import CustomAlert from './components/utils/CustomAlert';

function App({ loginSkip = false }) {
  // --- 로그인 관련 상태 추가 ---
  const [isLoggedIn, setIsLoggedIn] = useState(() => {
    if (loginSkip) return true;
    return sessionStorage.getItem('FORLINK_USER') !== null;
  });
  const [dataType, setDataType] = useState('Gen');
  const [openTabs, setOpenTabs] = useState([{ id: 'MAIN', label: 'Main', originalType: 'MAIN' }]);
  const [activeTab, setActiveTab] = useState('MAIN');
  const [alertConfig, setAlertConfig] = useState({
    isOpen: false,
    showCancel: true,
    title: '',
    message: '',
  });

  const [currentUser, setCurrentUser] = useState(() => {
    const savedUser = sessionStorage.getItem('FORLINK_USER');
    return savedUser
      ? JSON.parse(savedUser)
      : {
          empId: '',
          empName: '',
          dept: '',
          role: 1,
          securityLvl: 0,
        };
  });

  const [activePopup, setActivePopup] = useState(null); // 'ADD_EMP', 'MGMT_EMP' 또는 null

  const closePopup = () => setActivePopup(null);

  const closeAlert = () => setAlertConfig({ ...alertConfig, isOpen: false });

  useEffect(() => {
    if (loginSkip) {
      setIsLoggedIn(true);
    }
  }, [loginSkip]);

  const handleLoginSuccess = (userData) => {
    const userObj = {
      empId: userData.empId,
      empName: userData.empName,
      deptName: userData.deptName || '미지정',
      role: userData.authLevel || 1,
      securityLvl: userData.secLevel || 1,
    };

    setCurrentUser(userObj);
    setIsLoggedIn(true);
    sessionStorage.setItem('FORLINK_USER', JSON.stringify(userObj));
  };

  // --- 3. 로그아웃 핸들러 (참고용) ---
  const handleLogout = () => {
    sessionStorage.removeItem('FORLINK_USER');
    setIsLoggedIn(false);
    setOpenTabs([{ id: 'MAIN', label: 'Main', originalType: 'MAIN' }]); // 탭 초기화
  };

  // 2. 메뉴 클릭 핸들러 (탭 추가 및 전환)
  const handleMenuSelect = (type, label) => {
    // 팝업으로 띄울 메뉴인지 먼저 확인
    if (type === 'AddEmployee') {
      setActivePopup('ADD_EMP');
      return;
    }
    if (type === 'EmployeeManagement') {
      setActivePopup('MGMT_EMP');
      return;
    }

    if (['XYCorrelation', 'PHOTOMAP'].includes(type)) {
      setAlertConfig({
        isOpen: true,
        title: '개발중',
        message: '현재 메뉴는 개발 진행중입니다.',
      });
      return;
    }

    // 1. 싱글 탭 타입(하나만 생성)과 멀티 탭 타입 정의
    const isSingleTabType = ['AppLogViewer', 'About', 'Copyrights', 'MAIN'].includes(type);

    // 2. 이미 열려있는 동일 타입의 탭 확인
    const existingTabs = openTabs.filter((tab) => tab.originalType === type);
    const isAlreadyOpen = existingTabs.length > 0;

    // 3. 싱글 탭인데 이미 열려있다면 해당 탭으로 이동만 함
    if (isSingleTabType && isAlreadyOpen) {
      setActiveTab(existingTabs[0].id);
      return;
    }

    // 4. 새 탭을 위한 ID와 Label 생성
    let newInstanceId = type;
    let newLabel = label;

    if (!isSingleTabType) {
      // 멀티 탭인 경우에만 숫자(인덱스)를 붙임
      // 기존 탭들 중 가장 높은 숫자를 찾아 다음 번호 부여 (중간에 닫힌 탭 고려)
      const nextNum = existingTabs.length + 1;

      if (isAlreadyOpen) {
        newInstanceId = `${type}_${Date.now()}`; // 고유 ID를 위해 타임스탬프 활용 권장
        newLabel = `${label} (${nextNum})`;
      }
    }

    // 5. 탭 추가 및 활성화
    const newTab = {
      id: newInstanceId,
      label: newLabel,
      originalType: type,
    };

    setOpenTabs([...openTabs, newTab]);
    setActiveTab(newInstanceId);
  };

  // 3. 탭 닫기 핸들러
  const closeTab = (e, id) => {
    e.stopPropagation(); // 탭 전환 이벤트 전파 방지
    const newTabs = openTabs.filter((tab) => tab.id !== id);
    setOpenTabs(newTabs);

    // 닫은 탭이 활성 탭이었다면 마지막 남은 탭으로 이동
    if (activeTab === id && newTabs.length > 0) {
      setActiveTab(newTabs[newTabs.length - 1].id);
    }
  };

  if (!loginSkip && !isLoggedIn) {
    return <LoginPage onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div className="app-wrapper">
      <HeaderMenu
        className="Top-header"
        user={currentUser}
        onMenuType={(type, label) => handleMenuSelect(type, label)}
        onDataType={setDataType}
        onLogout={handleLogout}
      />

      {/* 5. 컨텐츠 렌더링 영역 */}
      {openTabs.map((tab) => (
        <div
          key={tab.id}
          style={{ display: activeTab === tab.id ? 'block' : 'none', height: '100%' }}
        >
          {/* originalType을 기준으로 렌더링하면 ID 뒤에 숫자가 붙어도 정확히 매칭됩니다. */}
          {tab.originalType === 'MAIN' && <MainPage />}
          {tab.originalType === 'FAB' && (
            <LayoutMonitoring
              user={currentUser}
              module={tab.originalType}
              dataType={dataType}
              moduleId={tab.label}
            />
          )}
          {tab.originalType === 'ET' && (
            <LayoutMonitoring
              user={currentUser}
              module={tab.originalType}
              dataType={dataType}
              moduleId={tab.label}
            />
          )}
          {tab.originalType === 'EDS' && (
            <LayoutMonitoring
              user={currentUser}
              module={tab.originalType}
              dataType={dataType}
              moduleId={tab.label}
            />
          )}
          {tab.originalType === 'Equivalence' && (
            <LayoutEquivalence user={currentUser} moduleId={tab.label} />
          )}
          {tab.originalType === 'Sleuth' && (
            <LayoutSleuth user={currentUser} moduleId={tab.label} />
          )}
          {tab.originalType === 'XYCorrelation' && (
            <LayoutEquivalence user={currentUser} moduleId={tab.label} />
          )}
          {tab.originalType === 'EDSMAP' && (
            <LayoutMap
              user={currentUser}
              module={tab.originalType}
              dataType={dataType}
              moduleId={tab.label}
            />
          )}
          {tab.originalType === 'DEFECTMAP' && (
            <LayoutMap
              user={currentUser}
              module={tab.originalType}
              dataType={dataType}
              moduleId={tab.label}
            />
          )}
          {tab.originalType === 'METROMAP' && (
            <LayoutMetro
              user={currentUser}
              module={tab.originalType}
              dataType={dataType}
              moduleId={tab.label}
            />
          )}
          {tab.originalType === 'MASSIVEMAP' && (
            <LayoutMassive user={currentUser} dataType={dataType} moduleId={tab.label} />
          )}
          {tab.originalType === 'AppLogViewer' && (
            <AppLogViewer user={currentUser} dataType={dataType} />
          )}
          {tab.originalType === 'About' && <AboutProject />}
          {tab.originalType === 'Copyrights' && <Copyrights />}
        </div>
      ))}
      {/* 4. 다이나믹 탭 바 영역 */}
      <div className="tabs-bar">
        {openTabs.map((tab) => (
          <div
            key={tab.id}
            className={`tab-item ${activeTab === tab.id ? 'active' : ''}`}
            onClick={() => setActiveTab(tab.id)}
          >
            <span>{tab.label}</span>
            <button className="close-btn" onClick={(e) => closeTab(e, tab.id)}>
              ×
            </button>
          </div>
        ))}
      </div>
      {/* --- 팝업 모달 레이어 추가 --- */}
      {activePopup && (
        <div className="modal-overlay" onClick={closePopup}>
          <div
            /* ADD_EMP와 MGMT_EMP 모두 리스트를 포함하므로 'mgmt-wide' 클래스를 공통 적용하거나 
         최소 너비를 80% 이상으로 잡는 클래스를 추가합니다. */
            className={`modal-content ${
              activePopup === 'MGMT_EMP' || activePopup === 'ADD_EMP' ? 'mgmt-wide' : 'add-standard'
            }`}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="modal-header">
              <h3 className="text-xl font-bold text-gray-800">
                {activePopup === 'ADD_EMP' ? '직원 등록 및 마스터 조회' : '직원 권한 및 조직 관리'}
              </h3>
              <button className="modal-close-x" onClick={closePopup}>
                &times;
              </button>
            </div>
            <div className="modal-body" style={{ height: '70vh', minHeight: '500px' }}>
              {activePopup === 'ADD_EMP' && (
                /* 기존에 작성한 Splitter 구조의 AddEmployeeForm */
                <AddEmployeeForm user={currentUser} dataType={dataType} onSuccess={closePopup} />
              )}
              {activePopup === 'MGMT_EMP' && (
                <EmployeeManagement user={currentUser} dataType={dataType} />
              )}
            </div>
          </div>
        </div>
      )}

      {/* Custom Alert 영역 */}
      {alertConfig.isOpen && (
        <CustomAlert
          title={alertConfig.title}
          message={alertConfig.message}
          showCancel={alertConfig.showCancel}
          onConfirm={closeAlert}
          onCancel={closeAlert}
        />
      )}
    </div>
  );
}

export default App;
