import React, { useState, useMemo, useEffect } from 'react';
import axios from 'axios';
import { captureLog } from './logService';

const EmployeeManagement = ({ user, dataType = 'Gen' }) => {
  const [currentUserRole] = useState('ADMIN');

  // 검색 관련 상태: inputValue(입력중), searchTerm(실제 필터 기준)
  const [inputValue, setInputValue] = useState('');
  const [searchTerm, setSearchTerm] = useState('');

  const [employees, setEmployees] = useState([]);
  const [originData, setOriginData] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [departments, setDepartments] = useState([]); // 실시간 부서 목록

  const localInitialData = [
    {
      EMP_ID: 'E2024001',
      EMP_NAME: '김철수',
      DEPT_NAME: 'IT 개발팀',
      AUTH_LEVEL: 1,
      SEC_LEVEL: 1,
      STATUS_CD: 'JOIN',
    },
    {
      EMP_ID: 'E2024002',
      EMP_NAME: '이영희',
      DEPT_NAME: '인사팀',
      AUTH_LEVEL: 2,
      SEC_LEVEL: 2,
      STATUS_CD: 'JOIN',
    },
    {
      EMP_ID: 'E2024003',
      EMP_NAME: '박지민',
      DEPT_NAME: '품질관리팀',
      AUTH_LEVEL: 1,
      SEC_LEVEL: 3,
      STATUS_CD: 'JOIN',
    },
  ];

  const localDeptMaster = [
    { cd: 'D001', name: 'IT 개발팀' },
    { cd: 'D002', name: '인사팀' },
    { cd: 'D003', name: '품질관리팀' },
    { cd: 'D004', name: '생산관리팀' },
    { cd: 'D005', name: '영업팀' },
  ];
  // 2. 부서 데이터 로딩 로직 추가
  useEffect(() => {
    const fetchDepartments = async () => {
      if (dataType === 'Api') {
        try {
          const response = await axios.get(
            'http://localhost:8081/api/v1/departments/with-employees',
          );
          // DTO 구조(deptCd, deptName)에 맞춰 매핑
          const mappedDepts = response.data.map((d) => ({
            cd: d.deptCd,
            name: d.deptName,
          }));
          setDepartments(mappedDepts);
        } catch (error) {
          console.error('부서 로드 실패:', error);
          setDepartments(localDeptMaster); // 실패 시 로컬 데이터로 폴백
        }
      } else {
        setDepartments(localDeptMaster);
      }
    };
    fetchDepartments();
  }, [dataType]);

  // 1. 데이터 로드 로직
  useEffect(() => {
    const fetchEmployees = async () => {
      setIsLoading(true);
      if (dataType === 'Gen') {
        setEmployees(localInitialData);
        setOriginData(localInitialData);
        setIsLoading(false);
      } else {
        try {
          const response = await axios.get('http://localhost:8081/api/v1/employees');
          // 백엔드(camelCase) -> 프론트(UPPER_CASE) 매핑
          const mappedData = response.data.map((emp) => ({
            EMP_ID: emp.empId,
            EMP_NAME: emp.empName,
            DEPT_CD: emp.department ? emp.department.deptCd : '',
            DEPT_NAME: emp.department ? emp.department.deptName : '',
            AUTH_LEVEL: emp.authLevel,
            SEC_LEVEL: emp.secLevel,
            STATUS_CD: emp.statusCd,
          }));
          setEmployees(mappedData);
          setOriginData(mappedData);
        } catch (error) {
          alert('서버 데이터를 불러오는데 실패했습니다.');
        } finally {
          setIsLoading(false);
        }
      }
    };
    fetchEmployees();
  }, [dataType]);

  // 2. 검색 핸들러 (Enter 키 전용)
  const handleKeyDown = (e) => {
    if (e.key === 'Enter') {
      setSearchTerm(inputValue);
    }
  };

  const filteredEmployees = useMemo(() => {
    return employees.filter(
      (emp) =>
        (emp.EMP_NAME || '').includes(searchTerm) ||
        (emp.EMP_ID || '').toLowerCase().includes(searchTerm.toLowerCase()) ||
        (emp.DEPT_NAME || '').includes(searchTerm),
    );
  }, [searchTerm, employees]);

  // 3. 수정 핸들러
  const handleUpdate = (empId, field, value) => {
    setEmployees((prev) =>
      prev.map((emp) => {
        if (emp.EMP_ID === empId) {
          if (field === 'DEPT_NAME') {
            // 부서명으로 마스터에서 코드를 찾아 함께 업데이트
            const selectedDept = departments.find((d) => d.name === value);
            return { ...emp, DEPT_NAME: value, DEPT_CD: selectedDept?.cd || '' };
          }
          return { ...emp, [field]: value };
        }
        return emp;
      }),
    );
  };

  // 4. 최종 저장 로직
  const handleFinalSave = async () => {
    const modifiedRows = employees.filter((emp) => {
      const original = originData.find((o) => o.EMP_ID === emp.EMP_ID);
      return JSON.stringify(original) !== JSON.stringify(emp);
    });

    if (modifiedRows.length === 0) {
      alert('변경사항이 없습니다.');
      return;
    }

    if (window.confirm(`${modifiedRows.length}건의 변경사항을 저장하시겠습니까?`)) {
      if (dataType === 'Gen') {
        setOriginData([...employees]);
        alert('테스트 모드: 로컬 저장 완료');
      } else {
        try {
          // 프론트(UPPER_CASE) -> 백엔드(camelCase) 페이로드 변환
          const payload = modifiedRows.map((row) => ({
            empId: row.EMP_ID,
            empName: row.EMP_NAME,
            // 백엔드 엔티티 구조에 맞춰 중첩 객체로 구성
            department: {
              deptCd: row.DEPT_CD,
              deptName: row.DEPT_NAME,
            },
            authLevel: row.AUTH_LEVEL,
            secLevel: row.SEC_LEVEL,
            statusCd: row.STATUS_CD,
          }));
          await axios.post('http://localhost:8081/api/v1/employees/batch-update', payload);
          setOriginData([...employees]); // 저장 성공 시 원본 동기화 (별표 제거)
          captureLog(user, 'UPDATE_EMPLOYEE', 'UPDATE');

          alert('서버에 성공적으로 저장되었습니다.');
        } catch (error) {
          alert('저장 중 오류가 발생했습니다.');
        }
      }
    }
  };

  const canEdit = ['ADMIN', 'MANAGER'].includes(currentUserRole);

  return (
    <div className="bg-white p-4">
      <div className="max-w-full mx-auto">
        <div className="flex justify-between items-center mb-6">
          {/* 검색창 영역 (Enter 입력 방식) */}
          <div className="relative w-80">
            <input
              type="text"
              placeholder="검색어 입력 후 Enter..."
              value={inputValue}
              onChange={(e) => setInputValue(e.target.value)}
              onKeyDown={handleKeyDown}
              className="w-full border border-gray-300 rounded-lg px-4 py-2 focus:ring-2 focus:ring-indigo-400 outline-none pl-10"
            />
            <span className="absolute left-3 top-2.5">🔍</span>
          </div>

          <div className="flex items-center gap-4">
            <p className="text-sm text-gray-500">
              모드: <span className="font-bold text-blue-600">{dataType}</span>
            </p>
            {canEdit && (
              <button
                onClick={handleFinalSave}
                className="bg-indigo-600 text-white px-5 py-2 rounded-lg font-bold shadow-md hover:bg-indigo-700"
              >
                최종 변경사항 저장
              </button>
            )}
          </div>
        </div>

        {/* 테이블 영역 */}
        <div className="overflow-x-auto rounded-xl border border-gray-200 shadow-sm">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-100 text-gray-600 text-xs uppercase">
                <th className="py-4 px-4 w-10"></th>
                <th className="py-4 px-3">사번</th>
                <th className="py-4 px-3">성명</th>
                <th className="py-4 px-3">부서 변경</th>
                <th className="py-4 px-3 text-center">권한(AUTH)</th>
                <th className="py-4 px-3 text-center">보안 등급(SEC)</th>
                <th className="py-4 px-3 text-center">상태</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-100">
              {isLoading ? (
                <tr>
                  <td colSpan="7" className="py-10 text-center">
                    데이터 로딩 중...
                  </td>
                </tr>
              ) : filteredEmployees.length > 0 ? (
                filteredEmployees.map((emp) => {
                  const isModified =
                    JSON.stringify(originData.find((o) => o.EMP_ID === emp.EMP_ID)) !==
                    JSON.stringify(emp);
                  return (
                    <tr key={emp.EMP_ID} className={`${isModified ? 'bg-yellow-50/50' : ''}`}>
                      <td className="py-4 px-4 text-orange-500 font-bold">
                        {isModified ? '*' : ''}
                      </td>
                      <td className="py-4 px-3 font-mono text-sm">{emp.EMP_ID}</td>
                      <td className="py-4 px-3 font-bold">{emp.EMP_NAME}</td>
                      <td className="py-4 px-3">
                        <select
                          disabled={!canEdit}
                          value={emp.DEPT_NAME}
                          onChange={(e) => handleUpdate(emp.EMP_ID, 'DEPT_NAME', e.target.value)}
                          className="border p-1 rounded text-sm w-full bg-transparent focus:ring-2 focus:ring-indigo-200 outline-none"
                        >
                          <option value="">부서 선택</option>
                          {departments.map((dept) => (
                            <option key={dept.cd} value={dept.name}>
                              {dept.name}
                            </option>
                          ))}
                        </select>
                      </td>
                      <td className="py-4 px-3 text-center">
                        <div className="flex flex-col items-center">
                          <label className="text-[9px] font-black text-indigo-400 uppercase mb-0.5">
                            Auth
                          </label>
                          <select
                            disabled={!canEdit}
                            value={emp.AUTH_LEVEL}
                            onChange={(e) =>
                              handleUpdate(emp.EMP_ID, 'AUTH_LEVEL', parseInt(e.target.value))
                            }
                            className="bg-transparent border-none p-0 text-sm font-bold text-center focus:ring-0 outline-none cursor-pointer"
                          >
                            {[1, 2, 3, 5, 9].map((lv) => (
                              <option key={lv} value={lv}>
                                {lv} Level
                              </option>
                            ))}
                          </select>
                        </div>
                      </td>
                      <td className="py-4 px-3 text-center">
                        <div className="flex flex-col items-center">
                          <label className="text-[9px] font-black text-blue-600 mb-0.5 uppercase tracking-tighter">
                            보안 Grade
                          </label>
                          <select
                            disabled={!canEdit}
                            name="SEC_LEVEL"
                            value={emp.SEC_LEVEL}
                            onChange={(e) =>
                              handleUpdate(emp.EMP_ID, 'SEC_LEVEL', parseInt(e.target.value))
                            }
                            className="bg-transparent border-none p-0 text-sm font-bold text-blue-800 focus:ring-0 outline-none cursor-pointer"
                          >
                            <option value="1">1등급 (일반)</option>
                            <option value="2">2등급 (기밀)</option>
                            <option value="3">3등급 (극비)</option>
                          </select>
                        </div>
                      </td>
                      <td className="py-4 px-3 text-center">
                        <span
                          className={`px-2 py-1 rounded text-[10px] font-bold ${emp.STATUS_CD === 'JOIN' ? 'bg-green-100 text-green-700' : 'bg-gray-100'}`}
                        >
                          {emp.STATUS_CD}
                        </span>
                      </td>
                    </tr>
                  );
                })
              ) : (
                <tr>
                  <td colSpan="7" className="py-20 text-center text-gray-400">
                    조회된 직원이 없습니다.
                  </td>
                </tr>
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default EmployeeManagement;
