import React, { useState, useLayoutEffect, useRef } from 'react';

const SetupWaferGeometry = ({ initialSettings, onClose, onApply, anchorRef }) => {
  const [localInputs, setLocalInputs] = useState(initialSettings);
  const [pos, setPos] = useState({ top: 0, left: 0 });
  const modalRef = useRef(null);

  useLayoutEffect(() => {
    if (anchorRef.current) {
      const rect = anchorRef.current.getBoundingClientRect();
      setPos({ top: rect.top, left: rect.right + 12 });
    }
  }, [anchorRef]);

  const handleChange = (e) => {
    const { name, value } = e.target;
    setLocalInputs((prev) => ({ ...prev, [name]: Number(value) }));
  };

  return (
    <>
      <div style={backdropStyle} onClick={onClose} />
      <div ref={modalRef} style={{ ...popupStyle, top: `${pos.top}px`, left: `${pos.left}px` }}>
        <div style={arrowStyle} />
        <header style={headerStyle}>
          <span style={titleIcon}>⚙️</span>
          <h4 style={titleStyle}>Wafer Geometry Setup</h4>
        </header>

        <div style={gridStyle}>
          {[
            { label: 'Wafer Size', name: 'waferSize' },
            { label: 'Edge Margin', name: 'waferEdge' },
            { label: 'Die Size X', name: 'dieSizeX' },
            { label: 'Die Size Y', name: 'dieSizeY' },
            { label: 'Scribe', name: 'scribeSize' },
          ].map((item) => (
            <div key={item.name} style={inputBox}>
              <label style={labelStyle}>{item.label}</label>
              <input
                name={item.name}
                type="number"
                value={localInputs[item.name]}
                onChange={handleChange}
                style={inputStyle}
              />
            </div>
          ))}
        </div>

        <div style={footerStyle}>
          <button onClick={onClose} style={cancelBtn}>
            Cancel
          </button>
          <button onClick={() => onApply(localInputs)} style={applyBtn}>
            Apply
          </button>
        </div>
      </div>
    </>
  );
};

// --- Styles (기존과 유사하나 컴팩트하게 유지) ---
const backdropStyle = { position: 'fixed', top: 0, left: 0, right: 0, bottom: 0, zIndex: 999 };
const popupStyle = {
  position: 'fixed',
  zIndex: 1000,
  width: '260px',
  backgroundColor: '#fff',
  borderRadius: '12px',
  boxShadow: '0 10px 25px rgba(0,0,0,0.1)',
  padding: '16px',
  border: '1px solid #e2e8f0',
  boxSizing: 'border-box',
};
const arrowStyle = {
  position: 'absolute',
  left: '-6px',
  top: '20px',
  width: '12px',
  height: '12px',
  backgroundColor: '#fff',
  transform: 'rotate(45deg)',
  borderLeft: '1px solid #e2e8f0',
  borderBottom: '1px solid #e2e8f0',
};
const headerStyle = {
  display: 'flex',
  alignItems: 'center',
  gap: '8px',
  marginBottom: '14px',
  paddingBottom: '10px',
  borderBottom: '1px solid #f1f5f9',
};
const titleStyle = { margin: 0, fontSize: '13px', fontWeight: '700', color: '#1e293b' };
const titleIcon = { fontSize: '14px' };
const gridStyle = { display: 'grid', gridTemplateColumns: 'repeat(2, 1fr)', gap: '10px' };
const inputBox = { display: 'flex', flexDirection: 'column', gap: '4px' };
const labelStyle = {
  fontSize: '10px',
  fontWeight: '600',
  color: '#64748b',
  textTransform: 'uppercase',
};
const inputStyle = {
  width: '100%',
  boxSizing: 'border-box',
  padding: '6px 8px',
  borderRadius: '4px',
  border: '1px solid #cbd5e1',
  fontSize: '12px',
  backgroundColor: '#f8fafc',
};
const footerStyle = { display: 'flex', gap: '8px', marginTop: '20px' };
const applyBtn = {
  flex: 1,
  padding: '8px',
  backgroundColor: '#2563eb',
  color: '#fff',
  border: 'none',
  borderRadius: '4px',
  cursor: 'pointer',
  fontWeight: '600',
  fontSize: '12px',
};
const cancelBtn = {
  flex: 1,
  padding: '8px',
  backgroundColor: '#fff',
  color: '#64748b',
  border: '1px solid #e2e8f0',
  borderRadius: '4px',
  cursor: 'pointer',
  fontSize: '12px',
};

export default SetupWaferGeometry;
