import React, { useState, useCallback, useRef, useEffect, useMemo } from 'react';
import TreeList from './TreeList';
import GridList from './GridList';
import axios from 'axios';

const WorkList = ({ module = 'FAB', dataType = 'Gen', onRun, onView }) => {
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [groupList, setGroupList] = useState([]); // [{groupkey...}, ...] 형태의 배열
  const [selectedGroups, setSelectedGroups] = useState([]); // 선택된 ID들의 배열 (["id1", "id2"])
  const [allGroups, setAllGroups] = useState([]);
  const [isLoading, setIsLoading] = useState(false);
  const [folderName, setFolderName] = useState('root');

  const [workList, setWorkList] = useState([]);
  const [selectedWorks, setSelectedWorks] = useState([]);

  // 리사이징을 위한 상태값 (너비와 높이)
  const [leftWidth, setLeftWidth] = useState(280); // 좌측 트리 너비
  const [topHeight, setTopHeight] = useState(300); // 우측 상단 그리드 높이

  const containerRef = useRef(null);

  // 1. 트리용 데이터 가공
  const treeData = useMemo(() => {
    if (allGroups.length === 0) {
      return [{ id: 'root-default', folder: 'root', groupName: 'Default Root' }];
    }
    return allGroups.map((g) => ({ ...g, id: g.groupKey }));
  }, [allGroups]);

  // 2. 초기 로드 및 allGroups 변경 시 GroupList 동기화
  const fetchGroups = async () => {
    if (dataType === 'Api') {
      setIsLoading(true);
      try {
        const response = await axios.get(
          `http://localhost:8081/api/v1/work-groups/module/${module}`,
        );
        setAllGroups(response.data);
      } catch (error) {
        console.error('Failed to fetch:', error);
        setAllGroups([]);
      } finally {
        setIsLoading(false);
      }
    } else {
      const mock = [
        { groupKey: 1, folder: 'root/testGroup/test1', groupName: 'testGroup1' },
        { groupKey: 2, folder: 'root/testGroup/test1', groupName: 'testGroup2' },
        { groupKey: 5, folder: 'root/testGroup', groupName: 'testGroup5' },
      ];
      setAllGroups(mock);
    }
  };

  useEffect(() => {
    fetchGroups();
  }, [dataType, module]);

  // --- 좌우 리사이징 로직 ---
  const handleSeparatorMouseDown = useCallback(
    (e) => {
      const startX = e.clientX;
      const startWidth = leftWidth;

      const onMouseMove = (moveEvent) => {
        const deltaX = moveEvent.clientX - startX;
        setLeftWidth(Math.max(150, startWidth + deltaX)); // 최소 너비 150px 제한
      };

      const onMouseUp = () => {
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      };

      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    },
    [leftWidth],
  );

  // --- 상하 리사이징 로직 ---
  const handleHorizontalSeparatorMouseDown = useCallback(
    (e) => {
      const startY = e.clientY;
      const startHeight = topHeight;

      const onMouseMove = (moveEvent) => {
        const deltaY = moveEvent.clientY - startY;
        setTopHeight(Math.max(100, startHeight + deltaY)); // 최소 높이 100px 제한
      };

      const onMouseUp = () => {
        document.removeEventListener('mousemove', onMouseMove);
        document.removeEventListener('mouseup', onMouseUp);
      };

      document.addEventListener('mousemove', onMouseMove);
      document.addEventListener('mouseup', onMouseUp);
    },
    [topHeight],
  );

  const loadGroupsInFolder = async () => {
    if (!folderName) return; // 폴더명이 없을 때 호출 방지

    try {
      setIsLoading(true);
      // 8081 포트를 명시적으로 추가합니다.
      const response = await axios.get('http://localhost:8081/api/v1/work-groups/folder', {
        params: { path: folderName },
      });

      setGroupList(response.data);
    } catch (error) {
      setGroupList([]); // 에러 시 빈 리스트로 초기화
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    if (dataType === 'Gen') {
      setGroupList(allGroups);
    } else {
      loadGroupsInFolder();
    }
  }, [folderName]);

  const handleSelectNode = (data) => {
    setSelectedCategory(data);
    setSelectedGroups([]);
    setWorkList([]);
    if (data && data.fullPath) {
      setFolderName(data.fullPath);
    }
  };

  const handleGroupChange = async (e) => {
    const { value } = e.target;
    setSelectedGroups(value);

    if (dataType === 'Gen') {
      let wList = [];
      for (let key = 0; key < 20; key++) {
        wList.push({
          workkey: String(key),
          title: 'Test Work List - ' + key,
          contents: 'LINE...,Process..Partid...설비...LotType...Step...Y1item...Y2item...' + key,
        });
      }
      setWorkList(wList);
    } else {
      if (value.length > 0) {
        try {
          // 콤마로 연결된 문자열 형태로 전달 (axios가 배열을 자동으로 처리해주기도 함)
          const response = await axios.get('http://localhost:8081/api/v1/work-list/groups', {
            params: { keys: value.join(',') },
          });
          // 서버에서 받아온 데이터를 GridList가 원하는 형식으로 변환
          const formattedList = response.data.map((item) => ({
            workkey: String(item.workKey), // ID를 문자열로
            title: item.workTitle, // workTitle -> title
            // JSON 객체(content)에서 필요한 정보를 뽑아 문자열로 합침
            contents: item.content
              ? `${item.content.line} | ${item.content.process} | ${item.content.equip} | ${item.content.title}...`
              : '내용 없음',
          }));

          setWorkList(formattedList);
        } catch (error) {
          console.error('업무 목록 멀티 조회 실패:', error);
        }
      } else {
        setWorkList([]);
      }
    }
    setSelectedWorks([]);
  };

  const handleWorkListChange = (e) => {
    const { value } = e.target;
    setSelectedWorks(value);
  };

  return (
    <div ref={containerRef} style={containerStyle}>
      {/* 1. 좌측 사이드바 */}
      <div style={{ ...sideBarStyle, width: `${leftWidth}px` }}>
        <TreeList
          indata={treeData}
          selectedData={handleSelectNode}
          showReload={true}
          onReload={fetchGroups}
        />
      </div>

      {/* 2. 좌우 구분 Splitter (실제 동작하는 바) */}
      <div style={verticalSplitter} onMouseDown={handleSeparatorMouseDown} />

      {/* 3. 우측 메인 컨테이너 */}
      <div style={mainContentStyle}>
        {/* 상단 섹션: Work List Group */}
        <div style={{ ...sectionStyle, height: `${topHeight}px`, flex: 'none' }}>
          <h5 style={{ ...titleStyle, paddingBottom: '2px', borderBottom: '2px solid #3182ce' }}>
            Work List Group {selectedCategory && `- ${selectedCategory.groupname}`}
          </h5>

          <div style={gridContainerStyle}>
            <GridList
              category="group"
              selectedValues={selectedGroups}
              options={groupList}
              onSelectChange={handleGroupChange}
            />
          </div>
        </div>

        {/* 상하 구분 Splitter (실제 동작하는 바) */}
        <div style={horizontalSplitter} onMouseDown={handleHorizontalSeparatorMouseDown} />

        {/* 하단 섹션: Work List */}
        <div style={{ ...sectionStyle, flex: 1, marginTop: '5px' }}>
          <div style={headerContainerStyle}>
            <h5 style={titleStyle}>Work List</h5>
            <div style={{ display: 'flex', gap: '5px', marginBottom: '2px' }}>
              <button style={setupBtnStyle}>View Work List</button>
              <button style={setupBtnStyle}>Execute Work List</button>
            </div>
          </div>
          <div style={gridContainerStyle}>
            <GridList
              category="worklist"
              selectedValues={selectedWorks}
              options={workList}
              onSelectChange={handleWorkListChange}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

const headerContainerStyle = {
  display: 'flex',
  justifyContent: 'space-between',
  alignItems: 'center',
  borderBottom: '2px solid #3182ce',
};
const setupBtnStyle = {
  padding: '4px 8px',
  fontSize: '11px',
  cursor: 'pointer',
  backgroundColor: '#fff',
  border: '1px solid #3182ce',
  borderRadius: '4px',
  color: '#3182ce',
};

// --- 스타일 정의 ---

const containerStyle = {
  display: 'flex',
  height: '85vh',
  width: '100%',
  overflow: 'hidden', // 전체 스크롤 방지
  backgroundColor: '#fff',
};

const sideBarStyle = {
  height: '100%',
  overflowY: 'auto',
  overflowX: 'hidden',
  backgroundColor: '#fcfcfc',
};

const verticalSplitter = {
  width: '6px',
  backgroundColor: '#eee',
  cursor: 'col-resize',
  flexShrink: 0,
  transition: 'background 0.2s',
};

const mainContentStyle = {
  flex: 1,
  display: 'flex',
  flexDirection: 'column',
  height: '100%',
  overflow: 'hidden', // 메인 컨테이너 스크롤 방지
};

const sectionStyle = {
  display: 'flex',
  flexDirection: 'column',
  padding: '2px 10px',
  overflow: 'hidden', // 외부 div 스크롤바 제거 핵심
};

// GridList를 감싸는 내부 박스 (스크롤이 필요하면 GridList 내부에서 처리하게 함)
const gridContainerStyle = {
  flex: 1,
  overflow: 'hidden', // 외부 스크롤 방지
};

const titleStyle = {
  margin: 0,
  fontSize: '13px',
};

const horizontalSplitter = {
  height: '6px',
  backgroundColor: '#eee',
  cursor: 'row-resize',
  flexShrink: 0,
};

export default WorkList;
