import { useEffect, useMemo, useRef, useState } from 'react';
import { generateBaseColors } from '../utils/ColorGenerator';

const ContourMap = ({
  params,
  waferDatas,
  onUpdate,
  title,
  zoomScale = 1,
  zoomOffset = { x: 0, y: 0 },
  isZoomInMode,
  onZoomChange,
  interactionMode,
}) => {
  const canvasRef = useRef(null);
  const [hoverInfo, setHoverInfo] = useState({ active: false, data: null, px: 0, py: 0 });

  const { mapType, waferSize, waferEdge, waferPixelSize, dieSizeX, dieSizeY } = params;
  const center = waferPixelSize / 2;
  const baseScale = (waferPixelSize - 20) / waferSize;
  const finalScale = baseScale * zoomScale;

  // 1. 색상 설정 (Contour용 부드러운 그라데이션)
  const stepCount = 100;
  const colors = useMemo(
    () => generateBaseColors(['#312e81', '#3b82f6', '#10b981', '#fbbf24', '#ef4444'], stepCount),
    [],
  );

  const colorMetrics = useMemo(() => {
    const isMetroCD = mapType === 'METRO-CD-Contour';

    // 1. mapType에 따른 소스 리스트 및 값 키 설정
    const sourceList = isMetroCD ? waferDatas?.dataList : waferDatas?.dieList;
    const valueKey = isMetroCD ? 'cdvalue' : 'itemValue';

    // 데이터가 없거나 비어있는 경우 대비
    if (!sourceList || sourceList.length === 0) {
      return { min: 0, max: 0, step: 1 };
    }

    // 2. 해당 필드값만 추출하여 유효한 숫자 필터링
    const values = sourceList
      .map((d) => d[valueKey])
      .filter((v) => typeof v === 'number' && !isNaN(v));

    if (values.length === 0) return { min: 0, max: 0, step: 1 };

    const min = Math.min(...values);
    const max = Math.max(...values);

    // 3. 단계별 색상 간격 계산
    const diff = max - min;
    const step = diff === 0 ? 1 : diff / stepCount;

    return { min, max, step };
  }, [waferDatas, mapType, stepCount]); // mapType 의존성 추가 필수

  // 2. 좌표 변환 함수
  const getMousePos = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    const clientX = e.touches ? e.touches[0].clientX : e.clientX;
    const clientY = e.touches ? e.touches[0].clientY : e.clientY;
    const mx = clientX - rect.left;
    const my = clientY - rect.top;

    const dx = (mx - center) / finalScale + zoomOffset.x;
    const dy = (center - my) / finalScale + zoomOffset.y;
    return { x: dx, y: dy, px: clientX, py: clientY };
  };

  /**
   * @param {Object} waferDatas - 전체 웨이퍼 데이터 객체
   * @param {number} resolution - 격자 해상도
   */
  const generateInterpolatedGrid = (waferDatas, resolution = 40) => {
    if (!waferDatas) return [];

    const isMetroCD = mapType === 'METRO-CD-Contour';

    const sourceList = isMetroCD ? waferDatas.dataList : waferDatas.dieList;
    const valueKey = isMetroCD ? 'cdvalue' : 'itemValue';

    if (!sourceList || sourceList.length === 0) return [];

    const effectiveRadius = waferSize / 2 - (waferEdge || 0);
    const gridStep = waferSize / resolution;
    const grid = [];

    // 1. 소스 데이터의 원점 보정 확인 (0부터 시작하는 좌표라면 center를 빼줘야 함)
    // 데이터가 0~300000 사이라면 중앙을 (0,0)으로 맞추기 위해 보정값이 필요할 수 있습니다.

    for (let gy = -waferSize / 2; gy <= waferSize / 2; gy += gridStep) {
      for (let gx = -waferSize / 2; gx <= waferSize / 2; gx += gridStep) {
        const distFromCenter = Math.sqrt(gx * gx + gy * gy);
        if (distFromCenter > waferSize / 2) continue;

        const isEdgeArea = distFromCenter > effectiveRadius;
        let totalWeight = 0;
        let weightedSum = 0;

        sourceList.forEach((item) => {
          let targetX, targetY;
          const val = item[valueKey];
          if (val === undefined || val === null || isNaN(val)) return;

          if (isMetroCD) {
            targetX = item.x;
            targetY = item.y;
          } else {
            targetX = item.x + (dieSizeX || item.width || 0) / 2;
            targetY = item.y + (dieSizeY || item.height || 0) / 2;
          }

          const dx = gx - targetX;
          const dy = gy - targetY;
          const distanceSq = dx * dx + dy * dy || 0.1; // 0 나누기 방지

          // 가중치 계산 (IDW)
          const weight = 1 / distanceSq;
          weightedSum += val * weight;
          totalWeight += weight;
        });

        if (totalWeight > 0) {
          grid.push({
            x: gx,
            y: gy,
            value: weightedSum / totalWeight,
            size: gridStep,
            alpha: isEdgeArea ? 0.4 : 1.0,
          });
        }
      }
    }
    return grid;
  };

  // 컴포넌트 내부에서 useMemo로 가공 데이터 관리
  const interpolatedData = useMemo(() => {
    // waferDatas 자체가 변경되거나 mapType이 변경될 때 재계산
    return generateInterpolatedGrid(waferDatas, 40);
  }, [waferDatas, mapType]); // mapType 추가 필수

  // 3. 드로잉 메인 로직
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !waferDatas?.dieList) return;

    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    canvas.width = waferPixelSize * dpr;
    canvas.height = waferPixelSize * dpr;
    ctx.scale(dpr, dpr);

    ctx.clearRect(0, 0, waferPixelSize, waferPixelSize);
    ctx.save();

    // 변환 설정: 캔버스 중앙을 (0,0)으로 잡음
    ctx.translate(center, center);
    ctx.scale(finalScale, -finalScale); // Y축 반전
    ctx.translate(-zoomOffset.x, -zoomOffset.y);

    // [Step 1] Wafer 영역 클리핑 (Notch 포함)
    const notchSize = waferSize * 0.015;
    ctx.beginPath();
    // 기본 원형
    ctx.arc(0, 0, waferSize / 2, 0, Math.PI * 2);
    ctx.clip();

    // [Step 2] Contour 드로잉
    interpolatedData.forEach((point) => {
      const { min, step } = colorMetrics;
      let colorIdx = Math.floor((point.value - min) / step);
      colorIdx = Math.max(0, Math.min(stepCount - 1, colorIdx));
      const color = colors[colorIdx];

      ctx.globalAlpha = 0.8;
      ctx.fillStyle = color;

      // [보정] point.x, point.y는 격자의 중심이므로,
      // 사각형을 그릴 때는 size의 절반만큼 이동시켜야 정확히 매핑됩니다.
      ctx.fillRect(
        point.x - point.size / 2,
        point.y - point.size / 2,
        point.size * 1.1, // 틈새 방지를 위해 1.1배
        point.size * 1.1,
      );
    });

    ctx.restore();

    // [Step 4] 웨이퍼 외곽 테두리 및 Notch 그리기
    ctx.save();
    ctx.translate(center, center);
    ctx.scale(finalScale, -finalScale);
    ctx.translate(-zoomOffset.x, -zoomOffset.y);

    // 1) 메인 원형 테두리
    ctx.beginPath();
    ctx.arc(0, 0, waferSize / 2, 0, Math.PI * 2);
    ctx.strokeStyle = '#334155';
    ctx.lineWidth = 1 / finalScale;
    ctx.stroke();

    ctx.restore();
  }, [interpolatedData, finalScale, zoomOffset]);

  // 4. 이벤트 핸들러 (Hover 정보 추출)
  const handleMouseMove = (e) => {
    const { x, y, px, py } = getMousePos(e);
    const isMetroCD = mapType === 'METRO-CD-Contour';

    let found = null;

    if (isMetroCD) {
      // METRO-CD: 점 데이터이므로 마우스 근처(일정 거리 안)에 있는 포인트를 찾음
      const threshold = waferSize * 0.02; // 감지 반경 (웨이퍼 크기의 2%)
      found = waferDatas.dataList?.find((d) => {
        const dist = Math.sqrt(Math.pow(x - d.x, 2) + Math.pow(y - d.y, 2));
        return dist < threshold;
      });
    } else {
      // MEASURE: Die 영역 내에 있는지 체크
      found = waferDatas.dieList?.find(
        (d) => x >= d.x && x <= d.x + d.width && y >= d.y && y <= d.y + d.height,
      );
    }

    if (found) {
      const displayValue = isMetroCD ? found.cdvalue : found.itemValue;
      const label = isMetroCD ? 'CD' : 'ID';

      setHoverInfo({ active: true, data: found, px, py });

      // 상위 컴포넌트 업데이트 알림
      onUpdate(`${label}: ${found.id || 'N/A'}, Value: ${displayValue?.toFixed(3)}`);
    } else {
      setHoverInfo({ active: false });
    }
  };

  return (
    <div style={containerStyle}>
      <canvas
        ref={canvasRef}
        className="contour-canvas-map"
        keyid={title}
        onMouseMove={handleMouseMove}
        onMouseLeave={() => setHoverInfo({ active: false })}
        style={{ cursor: 'crosshair', touchAction: 'none' }}
      />

      {hoverInfo.active && (
        <div style={tooltipStyle(hoverInfo.px, hoverInfo.py)}>
          <div style={tooltipHeaderStyle}>
            {mapType === 'METRO-CD-Contour' ? 'METRO CD CONTOUR' : 'MEASURE CONTOUR'}
          </div>
          <div style={tooltipGridStyle}>
            <span style={labelStyle}>ID:</span>
            <span>{hoverInfo.data.id || 'N/A'}</span>

            <span style={labelStyle}>VALUE:</span>
            <span style={{ color: '#10b981', fontWeight: 'bold' }}>
              {(mapType === 'METRO-CD-Contour'
                ? hoverInfo.data.cdvalue
                : hoverInfo.data.itemValue
              )?.toFixed(4)}
            </span>

            {/* METRO-CD 전용 정보 추가 가능 (X, Y 좌표 등) */}
            {mapType === 'METRO-CD-Contour' && (
              <>
                <span style={labelStyle}>X / Y:</span>
                <span style={{ fontSize: '9px' }}>
                  {hoverInfo.data.x.toFixed(0)} / {hoverInfo.data.y.toFixed(0)}
                </span>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// 스타일 상수는 WaferMap과 동일하게 사용 (생략)
const containerStyle = {
  width: '100%',
  height: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  overflow: 'hidden',
  position: 'relative', // 툴팁이나 드래그 UI의 기준점이 됩니다.
};
const tooltipStyle = (x, y) => ({
  position: 'fixed',
  left: x + 15,
  top: y + 15,
  backgroundColor: 'rgba(0,0,0,0.8)',
  color: '#fff',
  padding: '8px',
  borderRadius: '4px',
});
const tooltipHeaderStyle = { fontSize: '10px', color: '#aaa', marginBottom: '4px' };
const tooltipGridStyle = { display: 'grid', gridTemplateColumns: 'auto auto', gap: '5px' };
const labelStyle = { color: '#888' };

export default ContourMap;
