import React from 'react';

const CustomAlert = ({ title, message, onConfirm, onCancel, showCancel = false }) => {
  return (
    <div style={overlayStyle}>
      <div style={modalStyle}>
        {/* 1. 제목 좌측 정렬 및 아래 여백 추가 */}
        <h3 style={titleStyle}>{title}</h3>

        {/* 2. 메시지 영역 좌측 정렬 및 충분한 상하 여백 */}
        <div style={messageContainerStyle}>
          <p className="whitespace-pre-wrap" style={messageTextStyle}>
            {message}
          </p>
        </div>

        {/* 3. 버튼 그룹은 유지하되 우측 또는 중앙 배치 선택 가능 */}
        <div style={buttonGroupStyle}>
          {showCancel && (
            <button onClick={onCancel} style={cancelButtonStyle}>
              취소
            </button>
          )}
          <button onClick={onConfirm} style={confirmButtonStyle}>
            확인
          </button>
        </div>
      </div>
    </div>
  );
};

// --- 스타일 수정 부분 ---

const overlayStyle = {
  position: 'fixed',
  top: 0,
  left: 0,
  width: '100vw',
  height: '100vh',
  backgroundColor: 'rgba(0, 0, 0, 0.5)',
  display: 'flex',
  justifyContent: 'center',
  alignItems: 'center',
  zIndex: 1000,
};

const modalStyle = {
  backgroundColor: 'white',
  padding: '24px',
  borderRadius: '12px', // 조금 더 부드러운 라운드
  width: '400px',
  textAlign: 'left', // 텍스트 기본 정렬을 좌측으로 변경
  boxShadow: '0 10px 25px rgba(0,0,0,0.2)',
};

const titleStyle = {
  marginTop: 0,
  marginBottom: '16px', // 제목과 본문 사이 여백
  fontSize: '1.25rem',
  fontWeight: 'bold',
  color: '#1a202c', // 짙은 회색
};

const messageContainerStyle = {
  marginBottom: '28px', // 메시지와 하단 버튼 사이 충분한 여백
  minHeight: '40px', // 메시지가 짧아도 최소 높이 유지
};

const messageTextStyle = {
  fontSize: '1rem',
  lineHeight: '1.5',
  color: '#4a5568', // 본문용 회색
  margin: 0,
};

const buttonGroupStyle = {
  display: 'flex',
  justifyContent: 'flex-end', // 버튼을 우측으로 배치 (제목이 좌측일 때 밸런스가 좋음)
  gap: '12px',
};

const cancelButtonStyle = {
  padding: '8px 20px',
  cursor: 'pointer',
  border: '1px solid #e2e8f0',
  borderRadius: '6px',
  backgroundColor: 'white',
  fontWeight: '500',
  transition: 'background 0.2s',
};

const confirmButtonStyle = {
  padding: '8px 20px',
  cursor: 'pointer',
  border: 'none',
  borderRadius: '6px',
  backgroundColor: '#e53e3e',
  color: 'white',
  fontWeight: '500',
  transition: 'opacity 0.2s',
};

export default CustomAlert;
