import { useEffect, useMemo, useRef, useState } from 'react';
import {
  generateBaseColors,
  generateTurboColors,
  generateParulaColors,
  generateBinColors,
} from '../utils/ColorGenerator';

const WaferMap = ({
  params,
  waferDatas,
  onUpdate,
  isDetail,
  zoomScale = 1,
  zoomOffset = { x: 0, y: 0 },
  isZoomInMode,
  onZoomChange,
  interactionMode, // 'select' 또는 'drag' 추가
}) => {
  const canvasRef = useRef(null);
  const [hoverInfo, setHoverInfo] = useState({ active: false, type: '', data: null, px: 0, py: 0 });
  const [dragStart, setDragStart] = useState(null);
  const [dragEnd, setDragEnd] = useState(null);
  const { waferSize, waferPixelSize, mapType } = params;
  const CANVAS_PADDING = 10;
  const usableSize = waferPixelSize - 2 * CANVAS_PADDING;
  const center = waferPixelSize / 2;
  const scale = usableSize / waferSize;

  // 1. 색상 그라데이션 생성
  const stepCount = 100;
  const BASE = ['#d5d2e9', '#0363e1'];
  const measureColors = useMemo(() => generateBaseColors(BASE, stepCount), []);
  const binColors = useMemo(() => generateBinColors(), []);
  const colors = useMemo(() => generateParulaColors(stepCount), []);

  // 2. [추가] 색상 매핑을 위한 최소/단계 값 계산
  const colorMetrics = useMemo(() => {
    if (!waferDatas || (mapType !== 'MEASURE' && mapType !== 'METRO-CD')) {
      return { min: 0, step: 0 };
    }
    const min = waferDatas.min || 0;
    const max = waferDatas.max || 100;
    const step = (max - min) / stepCount || 1;
    return { min, step };
  }, [waferDatas, mapType, stepCount]);

  // 3. 툴팁 초기화
  const clearHover = () => {
    setHoverInfo({ active: false, type: '', data: null, px: 0, py: 0 });
    onUpdate('info...');
  };

  const [isPanning, setIsPanning] = useState(false);
  const [panStart, setPanStart] = useState({ x: 0, y: 0 });

  // 클라이언트 좌표 추출 (마우스/터치 공통)
  const getClientPos = (e) => {
    if (e.touches && e.touches.length > 0) {
      return { x: e.touches[0].clientX, y: e.touches[0].clientY };
    }
    return { x: e.clientX, y: e.clientY };
  };

  const handleStart = (e) => {
    const pos = getClientPos(e);

    if (isZoomInMode) {
      // 1. 박스 드래그 확대 모드
      setDragStart(getMousePos(e));
    } else if (zoomScale > 1) {
      // 2. 이동(Pan) 모드 시작
      setIsPanning(true);
      setPanStart({ x: pos.x, y: pos.y });
    }
  };

  const handleMove = (e) => {
    const pos = getClientPos(e);
    // 1. Drag 모드일 때만 Pan(이동) 로직 실행
    if (interactionMode === 'drag' && isPanning) {
      const dx = (pos.x - panStart.x) / finalScale;
      const dy = (pos.y - panStart.y) / finalScale;
      onZoomChange(zoomScale, {
        x: zoomOffset.x - dx,
        y: zoomOffset.y + dy,
      });
      setPanStart({ x: pos.x, y: pos.y });
      return; // 이동 중에는 툴팁 계산 안 함
    }

    // 2. Select 모드일 때만 툴팁 로직 실행
    if (interactionMode === 'select' && !dragStart) {
      // 기존 툴팁 계산 로직 (handleMouseMove의 내용)
      handleMouseMove(e);
    }

    // 3. ZoomBox 모드일 때 처리
    if (isZoomInMode && dragStart) {
      setDragEnd(getMousePos(e));
    }

    // 이동(Pan) 처리 루틴
    if (isPanning && !isZoomInMode) {
      // 현재 줌 배율을 고려한 실제 이동 거리 계산
      const dx = (pos.x - panStart.x) / finalScale;
      const dy = (pos.y - panStart.y) / finalScale;

      // Gallery.js의 zoomOffset을 업데이트 (중요: Y축 방향 주의)
      onZoomChange(zoomScale, {
        x: zoomOffset.x - dx,
        y: zoomOffset.y + dy, // Canvas Y축 반전 때문에 +로 계산
      });

      setPanStart({ x: pos.x, y: pos.y });
      return; // 이동 중에는 툴팁 무시
    }

    // 기존 드래그 박스 및 툴팁 로직 실행
    if (dragStart) {
      setDragEnd(getMousePos(e));
    } else {
      // 툴팁용 로직 (터치가 아닐 때만 권장)
      if (!e.touches) handleMouseMove(e);
    }
  };

  const handleEnd = () => {
    setIsPanning(false);

    // 확대 박스 드래그 종료 처리
    if (dragStart && dragEnd) {
      const width = Math.abs(dragEnd.x - dragStart.x);
      const height = Math.abs(dragEnd.y - dragStart.y);

      if (width > 5 && height > 5) {
        const newScale = waferSize / Math.max(width, height);
        const newOffsetX = (dragStart.x + dragEnd.x) / 2;
        const newOffsetY = (dragStart.y + dragEnd.y) / 2;
        onZoomChange(newScale, { x: newOffsetX, y: newOffsetY });
      }
    }
    setDragStart(null);
    setDragEnd(null);
  };

  // 1. 기본 배율과 사용자 줌 배율을 결합
  const baseScale = (waferPixelSize - 20) / waferSize; // 20은 마진
  const finalScale = baseScale * zoomScale;

  // 마우스 위치를 데이터 좌표로 역산 (줌/오프셋 반영)
  const getMousePos = (e) => {
    const rect = canvasRef.current.getBoundingClientRect();
    const mx = e.clientX - rect.left;
    const my = e.clientY - rect.top;

    // Canvas 중심점에서 얼마나 떨어져 있는지 계산 후 스케일과 오프셋 역산
    const dx = (mx - center) / finalScale + zoomOffset.x;
    const dy = (center - my) / finalScale + zoomOffset.y;
    return { x: dx, y: dy, rawX: mx, rawY: my };
  };

  // 4. 마우스 이동 핸들러
  const handleMouseMove = (e) => {
    // 1) 줌 상태가 반영된 데이터 좌표(x, y)와 마우스의 물리적 좌표(rawX, rawY)를 한 번에 가져옴
    const pos = getMousePos(e);
    const { x: dataX, y: dataY } = pos;

    if (dragStart) {
      setDragEnd(pos);
      return;
    }

    if (!canvasRef.current) return;

    // 2) 줌 배율(finalScale)에 따른 마우스 클릭/호버 판정 범위 조정
    // 화면상에서 약 8px 정도의 거리를 데이터 좌표계 상의 거리로 변환
    const threshold = 8 / finalScale;

    let found = null;
    let infoStr = 'info...';

    if (mapType === 'EDS') {
      found = waferDatas.dieList?.find(
        (d) => d.x <= dataX && dataX <= d.x + d.width && d.y <= dataY && dataY <= d.y + d.height,
      );
      if (found) infoStr = `ID: ${found.id}, BIN: ${found.bin}`;
    } else if (mapType === 'MEASURE') {
      found = waferDatas.dieList?.find(
        (d) => d.x <= dataX && dataX <= d.x + d.width && d.y <= dataY && dataY <= d.y + d.height,
      );
      if (found) infoStr = `ID: ${found.id}, Value: ${found.itemValue?.toFixed(2)}`;
    } else if (mapType === 'DEFECT') {
      found = waferDatas.dataList?.find(
        (d) => Math.sqrt((d.x - dataX) ** 2 + (d.y - dataY) ** 2) < threshold,
      );
      if (found) infoStr = `ID: ${found.id}, Type: ${found.type}, Size: ${found.size.toFixed(0)}`;
    } else if (mapType === 'METRO-CD') {
      found = waferDatas.dataList?.find(
        (d) => Math.sqrt((d.x - dataX) ** 2 + (d.y - dataY) ** 2) < threshold,
      );
      if (found) infoStr = `ID: ${found.id}, CD: ${found.cdvalue?.toFixed(2)}`;
    }

    if (found) {
      setHoverInfo({ active: true, type: mapType, data: found, px: e.clientX, py: e.clientY });
      onUpdate(infoStr);
    } else {
      clearHover();
    }
  };

  // 5. 캔버스 그리기 (핵심)
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || !waferDatas) return;

    const ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    canvas.width = waferPixelSize * dpr;
    canvas.height = waferPixelSize * dpr;
    ctx.scale(dpr, dpr);

    ctx.clearRect(0, 0, waferPixelSize, waferPixelSize);
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(0, 0, waferPixelSize, waferPixelSize);
    ctx.save();

    // 맵 이동 및 확대 적용
    ctx.translate(center, center);
    ctx.scale(finalScale, -finalScale);
    ctx.translate(-zoomOffset.x, -zoomOffset.y);

    // [Draw] 1. 외곽선
    ctx.beginPath();
    ctx.arc(0, 0, waferSize / 2, 0, Math.PI * 2);
    //ctx.strokeStyle = '#333';
    ctx.lineWidth = 1 / scale;
    ctx.strokeStyle = '#334155';
    ctx.stroke();

    // [Draw] 2. Notch
    const notchSize = waferSize * 0.015;
    // notch Draw를 위해 외곽선 일부 삭제
    ctx.beginPath();
    ctx.fillStyle = '#ffffff';
    ctx.fillRect(-notchSize / 2, -waferSize / 2 - 600, notchSize, notchSize * 1.2);
    // notch 그리기
    ctx.moveTo(-notchSize / 2, -waferSize / 2);
    ctx.lineTo(0, -waferSize / 2 + notchSize);
    ctx.lineTo(notchSize / 2, -waferSize / 2);
    ctx.stroke();

    // [Draw] 3. Die & Data
    const { min, step } = colorMetrics;

    waferDatas.dieList?.forEach((die) => {
      if (mapType === 'EDS') {
        ctx.fillStyle = die.bin === 1 ? '#392abe' : binColors[die.bin - 1] || '#b82323';
        ctx.fillRect(die.x, die.y, die.width, die.height);
      } else if (mapType === 'MEASURE') {
        const colorIdx = Math.floor((die.itemValue - min) / step);
        ctx.fillStyle = measureColors[Math.max(0, Math.min(stepCount - 1, colorIdx))];
        ctx.fillRect(die.x, die.y, die.width, die.height);
      } else {
        ctx.strokeStyle = '#bbbbca';
        ctx.lineWidth = 0.5 / scale / zoomScale;
        ctx.strokeRect(die.x, die.y, die.width, die.height);
      }
    });

    if (mapType === 'DEFECT') {
      // tooltip 강조 설정
      let x = 0;
      let y = 0;
      let fillcolor = '#ff0000';
      let tipDraw = false;
      let size = 1;
      waferDatas.dataList?.forEach((d) => {
        ctx.fillStyle = d.color || '#ff0000';
        ctx.beginPath();
        const r = params.realSize ? d.size / 2 : 2 / scale;
        if (hoverInfo && hoverInfo.active && hoverInfo?.data.id === d.id) {
          tipDraw = true;
          x = d.x;
          y = d.y;
          fillcolor = ctx.fillStyle;
          size = r;
        }
        ctx.arc(d.x, d.y, r / zoomScale, 0, Math.PI * 2);
        ctx.fill();
      });
      if (tipDraw) {
        ctx.fillStyle = fillcolor;
        ctx.beginPath();
        ctx.arc(x, y, (size * 2) / zoomScale, 0, Math.PI * 2);
        ctx.fill();
        ctx.lineWidth = 1000 / zoomScale;
        ctx.strokeStyle = '#080303';
        ctx.stroke();
      }
    }

    if (mapType === 'METRO-CD') {
      // tooltip 강조 설정
      let x = 0;
      let y = 0;
      let fillcolor = '#ff0000';
      let tipDraw = false;
      let size = 1;
      waferDatas.dataList?.forEach((cd) => {
        const colorIdx = Math.floor((cd.cdvalue - min) / step);
        ctx.fillStyle = colors[Math.max(0, Math.min(stepCount - 1, colorIdx))];
        ctx.beginPath();
        if (hoverInfo && hoverInfo.active && hoverInfo?.data.id === cd.id) {
          tipDraw = true;
          x = cd.x;
          y = cd.y;
          fillcolor = ctx.fillStyle;
        }
        ctx.arc(cd.x, cd.y, 2000 / zoomScale, 0, Math.PI * 2);
        ctx.fill();
      });
      if (tipDraw) {
        ctx.fillStyle = fillcolor;
        ctx.beginPath();
        ctx.arc(x, y, (2000 * 2) / zoomScale, 0, Math.PI * 2);
        ctx.fill();
        ctx.lineWidth = 1000 / zoomScale;
        ctx.strokeStyle = '#080303';
        ctx.stroke();
      }
    }

    ctx.restore();

    // 드래그 레이어는 데이터 변환과 무관하게 Raw Pixel로 그림
    if (dragStart && dragEnd) {
      ctx.strokeStyle = '#3b82f6';
      ctx.setLineDash([4, 4]);
      ctx.strokeRect(
        dragStart.rawX,
        dragStart.rawY,
        dragEnd.rawX - dragStart.rawX,
        dragEnd.rawY - dragStart.rawY,
      );
    }
  }, [waferPixelSize, waferDatas, finalScale, zoomOffset, dragEnd, hoverInfo.active]);

  return (
    <div style={containerStyle}>
      <canvas
        ref={canvasRef}
        className="wafer-canvas-map"
        width={waferPixelSize}
        height={waferPixelSize}
        onMouseDown={handleStart}
        onMouseMove={handleMove} // handleMove로 변경됨
        onMouseUp={handleEnd}
        onMouseLeave={() => {
          handleEnd();
          clearHover();
        }}
        onTouchStart={handleStart} // 모바일 터치 추가
        onTouchMove={handleMove} // 모바일 터치 추가
        onTouchEnd={handleEnd} // 모바일 터치 추가
        style={{
          display: 'block',
          // 모드에 따른 커서 정밀 제어
          cursor: isZoomInMode ? 'crosshair' : interactionMode === 'drag' ? 'grab' : 'default',
          touchAction: 'none',
        }}
      />

      {/* 예쁜 툴팁 */}
      {hoverInfo.active && (
        <div style={tooltipStyle(hoverInfo.px, hoverInfo.py)}>
          <div style={tooltipHeaderStyle}>{hoverInfo.type} DATA</div>
          <div style={tooltipGridStyle}>
            <span style={labelStyle}>ID:</span> <span style={valueStyle}>{hoverInfo.data.id}</span>
            <span style={labelStyle}>X/Y:</span>{' '}
            <span style={valueStyle}>
              {hoverInfo.data.x.toFixed(0)}/{hoverInfo.data.y.toFixed(0)}
            </span>
            {hoverInfo.type === 'EDS' && (
              <>
                <span style={labelStyle}>BIN:</span>{' '}
                <span style={{ ...valueStyle, color: '#f87171' }}>{hoverInfo.data.bin}</span>
              </>
            )}
            {hoverInfo.type === 'MEASURE' && (
              <>
                <span style={labelStyle}>VAL:</span>{' '}
                <span style={{ ...valueStyle, color: '#34d399' }}>
                  {hoverInfo.data.itemValue.toFixed(2)}
                </span>
              </>
            )}
            {hoverInfo.type === 'DEFECT' && (
              <>
                <span style={labelStyle}>TYPE:</span>{' '}
                <span style={{ ...valueStyle, color: '#f87171' }}>{hoverInfo.data.type}</span>
                <span style={labelStyle}>SIZE:</span>{' '}
                <span style={{ ...valueStyle, color: '#5779c2' }}>
                  {hoverInfo.data.size.toFixed(0)}
                </span>
              </>
            )}
            {hoverInfo.type === 'METRO-CD' && (
              <>
                <span style={labelStyle}>CD:</span>{' '}
                <span style={{ ...valueStyle, color: '#60a5fa' }}>
                  {hoverInfo.data.cdvalue.toFixed(2)}
                </span>
              </>
            )}
          </div>
        </div>
      )}
    </div>
  );
};

// --- 스타일 정의 ---

const containerStyle = {
  width: '100%',
  height: '100%',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
  overflow: 'hidden',
  position: 'relative', // 툴팁이나 드래그 UI의 기준점이 됩니다.
};

const tooltipStyle = (x, y) => ({
  position: 'fixed',
  left: x + 15,
  top: y + 15,
  backgroundColor: 'rgba(15, 23, 42, 0.9)',
  backdropFilter: 'blur(6px)',
  color: '#fff',
  padding: '12px',
  borderRadius: '8px',
  fontSize: '12px',
  pointerEvents: 'none',
  zIndex: 9999,
  border: '1px solid rgba(255,255,255,0.1)',
  boxShadow: '0 10px 15px -3px rgba(0,0,0,0.5)',
});

const tooltipHeaderStyle = {
  color: '#38bdf8',
  fontSize: '10px',
  fontWeight: '800',
  marginBottom: '6px',
  letterSpacing: '0.5px',
};
const tooltipGridStyle = { display: 'grid', gridTemplateColumns: 'auto auto', gap: '2px 10px' };
const labelStyle = { color: '#94a3b8', fontWeight: '500' };
const valueStyle = { fontWeight: 'bold', fontFamily: 'monospace' };

export default WaferMap;
